// Las 45 tareas del libro «Fundamentos de Fútbol», convertidas en tareas editables (noviembre 2026).
// SOLO se importa desde el servidor (/api/sesiones-objetivos); llegan a los tres planes. El gráfico es la parte gráfica recortada de la hoja del libro.
export const TAREAS_LIBRO = [{"nombre":"Circuito de desplazamientos","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"24","espacio":"8 metros","duracion":"7","objFisico":"Reconocer, aprender, repasar y perfeccionar los diferentes tipos de desplazamiento. Realizar activación muscular y cardiovascular en el jugador.","objTecnico":"Mejorar los desplazamientos frontales y laterales. Elevar la velocidad de desplazamientos laterales y de espaldas.","objTactico":"Aumentar la capacidad de repliegue en vigilancia. Potenciar la efectividad de progresión con visión panorámica.","objPsicologico":"Aplicar autoentrenamiento en todas las tareas. Incrementar la confianza del jugador en todos sus desplazamientos.","materiales":"balones, conos bajos o platos, conos","descripcion":"Se coloca los platos y los conos como muestra la figura y la distancia recomendada para cada edad.\n\nTramo \"A-B\" se utiliza para desplazamientos rectos de tipo: frontal, espalda, lateral izquierdo y derecho; en forma de arco y diagonal; caminando, trotando, corriendo, a velocidad, skipping, salto y zancada, ritmo homogéneo e intermitente.\n\nTramo \"C-D\" se utiliza para trayectorias de tipo zigzag y ondulatoria en desplazamientos: frontales, laterales (izquierdo y derecho), de espaldas; y, con diferentes intensidades, caminando, trotando, corriendo, a velocidad, skipping y salto.","reglas":"Señalar las trayectorias con cinta elástica o en alguna parte de la cancha que se encuentre señalada; repetir el trayecto para corregir los movimientos; al primer jugador realizar un desplazamiento de ejemplo para que el resto del equipo lo imite; ampliar la distancia horizontal de los conos; indicar los porcentajes de velocidad al correr.","observaciones":"Aumentar la distancia del trayecto según la edad del equipo.","movimientosObservar":"Instrucciones claras de desplazamiento; comenzar con lineales y terminar con tramo \"C-D\"; realizar la mayor cantidad de nomenclaturas; postura recta y cabeza levantada; braceo de acuerdo a la intensidad.","codigo":"Cfís-01","id":"libro-01","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-01.jpg"},{"nombre":"Dos equipos en círculo","categoria":"Técnico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Calentamiento o regenerativo","faseJuego":"Iniciación","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"20","espacio":"18 metros de diámetro o círculo central","duracion":"8","objFisico":"Mejora y dominio de espacio y tiempo. Calentar músculos y liquido sinovial de articulaciones.","objTecnico":"Mejorar el pase en salida de juego. Precisión en devolución de un solo toque.","objTactico":"Elevar el sentido de conservar las distancias. Movilidad en apoyo de jugadas cortas.","objPsicologico":"Aumento de la comunicación con la persona que tiene el balón, atención. Aumento de confianza en sus movimientos.","materiales":"balones, conos bajos o platos, cinta elástica (5 m)","descripcion":"Se forma un círculo con platos o cinta elástica para definir el espacio de trabajo, se puede utilizar el centro del campo. Se divide al grupo de trabajo en 2 equipos del mismo número de jugadores, uno se colocará fuera del círculo y el otro adentro. Los jugadores que se encuentran afuera ocuparán un sitio y estarán siempre estáticos, cada uno tendrá un balón e iniciará el ejercicio, a la señal del entrenador, con un pase hacia cualquier jugador de adentro del círculo que se acerque. Los jugadores de adentro del círculo estarán en constante movimiento, se acercan aleatoriamente a los jugadores de afuera para solicitar el balón y devolverá en un solo pase, luego de hacerlo, buscará otro jugador para repetir la acción hasta terminar el tiempo.\n\nTerminada la tarea se intercambiarán posiciones los de adentro con los de afuera del círculo.\n\nLas superficies de pase que se utilizarán en las tareas son: Borde interno, borde externo, empeine, punta, planta, muslo, pecho-borde interno, cabeza, hombro, taco, rabona, etc.","reglas":"El jugador de afuera del círculo realiza control y pase (2 contactos); el jugador de afuera del círculo utiliza la mano en tareas como muslo, pecho, cabeza, hombro; el jugador de adentro alterna pierna izquierda y pierna derecha en cada devolución; debe existir balones extras fuera del círculo en caso de que el balón abandone el área de trabajo; el jugador de adentro llama por el nombre para anticipar que va al jugador de afuera; la intensidad del trabajo es del 60%; categorías de 8 a 10 años sólo pases con tren inferior.","observaciones":"","movimientosObservar":"La devolución a un solo toque; el movimiento continuo y constante; pases en fuerza y dirección correcta; el pase de inicio de forma correcta para que la devolución sea de la misma forma; la petición de pase con voz firme y clara.","codigo":"Ctéc-02","id":"libro-02","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-02.jpg"},{"nombre":"Cuida tu balón o Rey del balón","categoria":"Técnico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Calentamiento o regenerativo","faseJuego":"Creación ofensiva","momentoJuego":"Transición ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"20","espacio":"6 metros de diámetro","duracion":"6","objFisico":"Mejora de equilibrio en carga. Aumento de pulsaciones y calentamiento de músculos para el trabajo principal.","objTecnico":"Mejora en la protección del balón con el cuerpo. Aumento de habilidad de conducción en espacios cortos.","objTactico":"Desarrollo de visión panorámica con balón. Detección de espacios de salida.","objPsicologico":"Voluntad en alcanzar la victoria. Mejora de competitividad.","materiales":"balones, cinta elástica (5 m), conos bajos o platos","descripcion":"Este ejercicio lo identificamos como Cuida tu balón o Rey del balón.- Se delimita un círculo con la cinta o conos, de preferencia podemos utilizar el centro de la cancha, cada jugador va a tener un balón en sus pies. Después de la señal van a conducir el balón por dentro del círculo cuidando su balón y al mismo tiempo debe quitar el balón de un compañero. En el momento que quita o encuentra un balón en su camino chutará o pateará lo más lejos del círculo. El jugador que ha perdido el balón deberá ir a buscarlo, regresar afuera del círculo y hacer dominio libre hasta que comience una nueva serie del ejercicio. El o los jugadores que terminado el tiempo quede dentro del círculo con su balón serán los triunfadores y acumularán un punto.\n\nSi un jugador abandona el círculo por cualquier motivo, quedará eliminado.\nEl jugador que se queda inmóvil con el balón será descalificado por el entrenador y hacer dominadas fuera del círculo.","reglas":"Variantes: el jugador puede regresar 15 segundos antes que termine el tiempo para motivar su regreso; si no existe un balón para cada jugador, se alternarán grupos en las repeticiones; se puede ingresar jugadores sin balón y su único objetivo será robar y tirar balones fuera del círculo; mientras más corto sea el espacio de trabajo aumentará la técnica de protección de balón; el jugador que gane más puntos será reconocido de la forma que decida el entrenador; se puede eliminar el patear el balón hacia afuera, dos o tres jugadores que quiten el balón, si el jugador perdió el balón, deberá buscar un nuevo balón con un jugador diferente.","observaciones":"","movimientosObservar":"La conducción debe ser rápida utilizando varios contactos con el pie; en la protección del balón se utiliza el cuerpo; se amonestará al jugador que tenga poca actitud; observar que todos los jugadores estén en movimiento.","codigo":"Ctéc-03","id":"libro-03","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-03.jpg"},{"nombre":"Rondo simple en círculo","categoria":"Técnico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Calentamiento o regenerativo","faseJuego":"Creación ofensiva","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"7","maxJugadores":"20","espacio":"10 metros de diámetro","duracion":"6","objFisico":"Mejora de forma breve la adaptación del campo y balón. Aumentar ritmo cardiaco, calentamiento de músculos y reacción de los mismos.","objTecnico":"Aumento en interceptación de pase. Mejora de pases laterales y frontales entre líneas.","objTactico":"Activa vigilancia y afina la presión y el acoso. Calcula de mejor manera los tiempos de pase y retención de balón.","objPsicologico":"Control y agresividad para recuperar el balón. Aumenta rápidamente la motivación del equipo.","materiales":"balones, chalecos o petos","descripcion":"Rondo simple.- Se debe formar un círculo con platos o con la cinta elástica, colocamos a todos los jugadores fuera del círculo en distancias iguales.\n\nAleatoriamente se escoge a una o dos personas que van a ir dentro del círculo, el ejercicio comienza desde fuera del círculo y los dos jugadores que están en el centro deben quitar o interceptar el pase de los jugadores que se encuentran afuera, cuando el pase es interceptado por cualquiera de los dos jugadores que están en el centro se detiene el ejercicio, se suplantan por dos nuevos jugadores de afuera del círculo.\n\nRegularmente entra la persona que falló el último pase acompañado de la persona que se encuentra a la izquierda, a la derecha o que escoge al azar.\n\nSi el balón se aleja de la zona de trabajo, se la suplantará por el balón más cercano para que el esfuerzo sea lo más continuo posible.","reglas":"Los jugadores de afuera del círculo se rigen a un solo contacto con el balón; los jugadores de adentro deben apoderarse completamente del balón; el cambio de jugadores puede ser por tiempo o por conteo de toques consecutivos; puede haber uno o tres jugadores dentro del círculo, dependiendo del total de personas; para edades mayores a 16 años el balón puede ser sólo aéreo; si el pase entre jugadores es entre líneas se contará doble, así como el paso entre las piernas; el primer pase puede ser libre.","observaciones":"","movimientosObservar":"El movimiento del balón debe ser continuo; todos los jugadores deben ingresar al centro; los jugadores del centro: uno debe atacar el balón y el otro debe atacar al pase; formar un ambiente constante de motivación y reto.","codigo":"Ctéc-04","id":"libro-04","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-04.jpg"},{"nombre":"Rueda de pase dentro del círculo","categoria":"Técnico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Calentamiento o regenerativo","faseJuego":"Creación ofensiva","momentoJuego":"Ataque","tipoTarea":"Ruedas de pase","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"25","espacio":"10 metros de diámetro o centro del campo.","duracion":"5","objFisico":"Adaptación a ritmos de juego rápidos. Activar rápidamente el ritmo cardíaco.","objTecnico":"Rapidez de pase en salida de juego. Mejora el pase en proyección del juego.","objTactico":"Aumenta la atención en vigilancia. Velocidad en proyecciones y ritmos en jugadas.","objPsicologico":"Aumenta la toma de decisión en el pase al compañero antes de recibir el balón. Genera confianza de movimientos.","materiales":"balones, cinta elástica (5 m), chalecos o petos","descripcion":"Se forma la zona de trabajo, puede ser en forma de círculo, un rectángulo o un cuadrado; con platos de colores o con la cinta elástica. Todos los jugadores deben colocarse afuera del perímetro, Igualmente que los balones. Comienza el jugador (A) realizando un pase hacia cualquier jugador del círculo e inmediatamente se desplaza al lugar del jugador que recibió el pase. Consecutivamente sucederá con los siguientes pases.\nTodos los pases deben ser a un contacto, si el balón sale del ejercicio, inmediatamente se debe utilizar el balón más cercano para dar continuidad a la tarea.","reglas":"El jugador debe anticipar en voz alta el nombre del jugador que antes de recibir el balón; se puede colocar un objetivo de pases consecutivos; en edades mayores de 16 años se puede realizar pases de media altura y altos; se pueden colocar conos en el centro para simular posicionamiento del contrario; cada jugador puede elegir el nombre de un país, ciudad, color, etc., para aumentar la memoria y atención; alternar pase con pie izquierdo y derecho.","observaciones":"","movimientosObservar":"","codigo":"Ctéc-05","id":"libro-05","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-05.jpg"},{"nombre":"Circuito de desplazamientos con estacas, vallas y aros","categoria":"Físico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"25","espacio":"8 metros de inicio a fin del tramo","duracion":"7","objFisico":"Aumento de coordinación espacios cortos y largos. Alcanzar ritmo cardíaco de calentamiento. Aumento de fuerza, y velocidad de desplazamiento.","objTecnico":"Desarrollo de atención y desplazamiento frontal. Ampliar las formas de desplazamiento en transición.","objTactico":"Velocidad y voluntad en repliegue. Ganar visión panorámica sin balón","objPsicologico":"Auto disciplina y auto corrección. Aplicación de ejemplo en disciplina.","materiales":"Conos bajos o platos, estacas o picas, escaleras de coordinación, aros o anillos, vallas","descripcion":"Se forma un circuito con 5 ejercicios.\nTramo A: Desplazamiento lateral con estacas, al finalizar la última estaca finaliza con desplazamiento frontal hasta el plato en 70 - 80%. Tramo B: Desplazamiento frontal, en las escaleras una pisada en cada espacio con rodillas alzadas, desplazamiento al plato en 70 - 80%. \nTramo C: Llega al primer plato, desplazamiento frontal plato de la izquierda después desplazamiento de espaldas al primer plato, continúa desplazamiento frontal al plato de la derecha, regresa de espaldas nuevamente al primer plato y finalmente desplazamiento frontal al 80%. Tramo D: Se coloca aros a diferentes distancias, comienzan en distancias pequeñas alargando la distancia en el centro y acortando las distancias al final del ejercicio.\nTramo E: Se recomienda hacerlo al final, comprende de tres saltos en vallas y arranque en velocidad.","reglas":"Variantes: el tramo \"A\" puede hacerse con balón; en el tramo \"B\" se puede cambiar el ritmo en cada escalera, alternando izquierda y derecha; para niños de 8 a 10 años una sola escalera; todo el tramo \"C\" puede ser en velocidad; se realiza estiramientos de tren inferior antes de realizar el siguiente ejercicio; se pueden dividir a los jugadores en 4 grupos para que realicen los ejercicios simultáneos; en el último salto del tramo \"E\" se puede lanzar un balón para devolución con cabeza en el salto.","observaciones":"Se puede utilizar como calentamiento de tareas físicas en intensidades bajas.","movimientosObservar":"En todos los ejercicios el jugador debe mantener postura corporal recta, cabeza levantada y la mirada al frente. Especialmente cuando el trayecto es de espaldas; corregir desplazamientos y movimientos de sincronización; concientizar auto disciplina.","codigo":"Cfís-06","id":"libro-06","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-06.jpg"},{"nombre":"Circuito de coordinación con escalera y eslalon","categoria":"Físico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Calentamiento o regenerativo","faseJuego":"Vacío","momentoJuego":"Transición ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"","maxJugadores":"","espacio":"16 metros de inicio a fin del trayecto","duracion":"6","objFisico":"Aclimatación de esfuerzo para tareas de fuerza. Elevar el ritmo cardíaco y calentamiento de músculos para la parte principal.","objTecnico":"Agudizar el sentido de desplazamiento con obstáculos. Progresión de pase preciso después del esfuerzo.","objTactico":"Marcación continua de tiempos. Adaptación de progresión con interrupciones.","objPsicologico":"Autorregulación de movimientos. Acrecentar y valorar el sentido de sacrificio.","materiales":"balones, conos bajos o platos, estacas o picas, escaleras de coordinación, vallas","descripcion":"Tramo A.- Coordinación con escalera una o dos pisadas en el espacio regresa al punto inicial y realizarlas con repeticiones recomendadas. \nTramo B.- Desplazamiento lateral en eslalon.\nTramo C.- Levanta sólo la pierna derecha con rodilla flexionada en la primera valla, la izquierda en la segunda valla y así consecutivamente. \nTramo D.- Saltar la valla e impacta en el aire el balón que es proporcionado por el entrenador.\n\nTodos los ejercicios deben comenzar en el primer plato amarillo, es decir, los tramos son acumulativos (A, A-B, A-C, A-D).","reglas":"Tramo A puede pasar de una forma diferente, dejando la creatividad al jugador; tramo B puede ser desplazamiento de espaldas; tramo C también se alterna de espaldas; tramo D el lanzamiento puede ser a media altura o alto para que el jugador resuelva la devolución. (devolución con cabeza, pecho, muslo, rodilla, pie levantado).","observaciones":"Se utiliza también como tarea física aumentando la carga de trabajo dependiendo de la edad de jugadores.","movimientosObservar":"Coordinación de pies en cada uno de los escalones de la escalera; desplazamiento siempre lateral y apoyo de la pierna contraria al cambiar de sentido; levantar la rodilla al máximo; salto fuerte, caída equilibrada y pase preciso; respiraciones profundas en el retorno.","codigo":"Cfís-07","id":"libro-07","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-07.jpg"},{"nombre":"Zombies o la cadena","categoria":"Calentamiento","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"Actividades lúdicas","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"25","espacio":"15 a 20 metros de inicio a fin","duracion":"5","objFisico":"Adaptación de esfuerzo para tareas de velocidad o resistencia. Aumentar rápidamente el ritmo cardíaco y calentamiento de músculos para la parte principal.","objTecnico":"Incrementar velocidad y agilidad de progresión. Controlar tiempos y velocidad en la zona final.","objTactico":"Mejorar el sentido de cobertura y acoso. Identificar espacios de progresión.","objPsicologico":"Aprender el sentido de autocontrol. Identificar, valorar e incrementa el trabajo en equipo.","materiales":"chalecos o petos","descripcion":"Zombies.- Se elige un jugador al azar que se colocará en un extremo del área del portero denominado Zombie y el resto de jugadores en el otro extremo. A la señal todos los jugadores deberán desplazarse al otro extremo para encontrar una zona neutral y estar a salvo, el jugador que se encuentra solo intentará atrapar o topar en el trayecto la mayor cantidad de jugadores, los jugadores que han sido tocados se convertirán en zombies. Continúa con el ejercicio pero los jugadores que son zombies estarán juntos de la mano para poder atrapar a los de otros jugadores, si se sueltan no podrán convertir a nadie.\n\nEl jugador que abandone la zona de trabajo indicado por el entrenador automáticamente se convertirá en zombie. Se repetirán las veces que sean necesarias hasta que quede un solo jugador.\n\nEste ejercicio es muy valioso para diferenciar el trabajo individual y en equipo, y, cómo se pueden generar estrategias para lograr objetivos en conjunto.","reglas":"Variantes: se pueden crear parejas o trios de zombis, siempre agarrados de las manos; se pueden colocar obstáculos en el trayecto, si el jugador los toca, se convierte en zombi; cuando el grupo de Zombis sea mayor de 4 se reforzará el concepto de trabajo de equipo, se puede dar un tiempo de 10 segundos para que conformen una táctica o estrategia; si la estrategia elegida no funcionó, se la cambia, dejándolos conocer que hay otras maneras de lograrlo; el ó los zombies pueden atrapar únicamente en una franja central del área.","observaciones":"","movimientosObservar":"Todos los jugadores deben ir en el menor tiempo a la otra zona; motivar continuamente a los dos bandos; identificar a los jugadores que toman liderazgo; repetir el ejercicio si se termina pronto; reforzar el valor de trabajo en equipo.","codigo":"Cfís-08","id":"libro-08","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-08.jpg"},{"nombre":"Cinco porterías","categoria":"Físico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Anaeróbica","faseJuego":"Finalización","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"14","maxJugadores":"22","espacio":"40 x 30 metros","duracion":"15","objFisico":"Adaptarse al esfuerzo mixto. Alcanzar rápidamente pulsaciones altas, para tareas de resistencia.","objTecnico":"Generar instinto de anticipación e interceptación. Mejorar el pase a largo en profundidad y cambio de lado.","objTactico":"Aumentar el sentido de apoyo en temporización. Ampliar el concepto de profundidad.","objPsicologico":"Conocer el sentido de autorregulación. Desarrollar un alto sentido de competitividad.","materiales":"balones, estacas o picas, chalecos o petos","descripcion":"Se forman 5 porterías como muestra la figura, puede ser con platos, conos o vallas. Se crean 2 equipos iguales o en superioridad numérica, el objetivo del ejercicio es que el equipo que tenga el balón pueda hacer goles continuos en las porterías que se encuentran dentro de la cancha o el campo; si el jugador de un equipo hace un gol en una portería, pueden dirigirse a otra mientras tengan la posesión del balón, sumando puntos para el equipo.\n\nEl equipo contrario debe apoderarse del balón para marcar sus goles y el ejercicio es constantemente continuo.\n\nEl gol es únicamente válido cuando el jugador traspasa la línea de meta en conducción.","reglas":"Variantes: se puede colocar marca personal, en zona o mixta; el gol es válido únicamente cuando el balón pase por la línea y exista un receptor al otro lado; el gol es válido siempre y cuando antes haya existido una pared entre dos jugadores; el gol es válido solo cuando haya pasado el balón por cada uno de los jugadores del equipo; el gol es válido cuando haya existido un desdoble previo; el gol es válido cuando haya un cambio largo de balón; se puede colocar uno o dos jugadores que actuarán como comodines.","observaciones":"","movimientosObservar":"","codigo":"Cfís-09","id":"libro-09","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-09.jpg"},{"nombre":"Rondo con apoyos y cuadrante central","categoria":"Táctico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"6","maxJugadores":"8","espacio":"7 x 7 metros","duracion":"6","objFisico":"Distinguir la orientación correcta hacia el balón. Aumentar ritmo cardiaco y temperatura corporal para ejercicios tácticos.","objTecnico":"Afinar la precisión y fuerza del pase corto. Mejorar la técnica de la carga para apoderarse del balón.","objTactico":"Identificar los espacios y responsabilidades en cobertura. Elevar la habilidad de desmarque y apoyo.","objPsicologico":"Reconocer el sentido de autoconfianza. Reforzar el significado de compañerismo.","materiales":"balones, conos bajos o platos, cinta elástica (5 m)","descripcion":"Se forma un cuadrante con cintas o platos para realizar un rondo con apoyos, dentro del cuadrante mayor se formará también un cuadrante pequeño aproximadamente de un metro cuadrado, como muestra la figura. Se hacen 3 equipos de 4 jugadores por cada estación, correctamente identificados por colores, un equipo se colocará fuera del cuadrante como apoyo y adentro los equipos restantes, generarán juego interno.\n\nComienza el ejercicio desde el centro del cuadrante; el equipo que se apodere primero del balón deberá hacer toques continuos, contando cada uno de ellos hasta el final de la tarea, pueden apoyarse con los comodines que se encuentran afuera. Los comodines tendrán juego libre y deben jugar máximo a dos contactos (recepción pase). Es prohibido el pase entre comodines externos.\nCada vez que la pelota salga del cuadrante se tomará la pelota más cercana para darle continuidad al ejercicio y aprovechar el tiempo del esfuerzo.\nSi el equipo logra hacer un pase entre lineas que recorra por dentro del cuadrante interior, se contabilizará con doble puntaje.","reglas":"Variantes: uno de los dos equipos internos durante el tiempo de trabajo mantendrá el control de la pelota y la misión del otro equipo será el quitar la pelota; se podrán realizar pases entre comodines sólo si el balón pasa por el cuadrante interno (pase entre líneas); cuando el balón se encuentre en poder de los comodines, un jugador del equipo que está en modo defensa presionará al balón, otro presionará al posible receptor y el otro se colocará en la zona para evitar el pase entre líneas. El objetivo es sistematizar el movimiento de defensa; los comodines y/o jugadores en modo ataque jugarán a un solo contacto.","observaciones":"","movimientosObservar":"Recepciones y pases precisos; correcta orientación de acuerdo al balón; movimientos rápidos; ambición para recuperar o quitar el balón; velocidad de decisión en el pase; distancia en las sincronizaciones de coberturas; dar confianza en los movimientos.","codigo":"Ctác-10","id":"libro-10","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-10.jpg"},{"nombre":"Circuito de pase","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Fútbol base","minJugadores":"8","maxJugadores":"20","espacio":"4 metros de inicio a fin","duracion":"13","objFisico":"Sincronizar ojo, pie y balón. Orientar correctamente el cuerpo para pases precisos. Desarrollar resistencia aeróbica.","objTecnico":"Reconocer, aprender, repasar y perfeccionar los tipos de pases a ras de suelo. Desarrollar precisión en pase. Aplicar de forma correcta las superficies de contacto del pie para pases rasos.","objTactico":"Mejorar la salida de juego. Afinar el pase en zona final.","objPsicologico":"Aprender y utilizar la herramienta de Autocorrección. Motivación de equipo.","materiales":"balones, conos, cinta elástica (5 m)","descripcion":"Circuito de pase\n\nNivel 0.- se coloca un jugador frente al otro a una distancia corta, realizan pases continuos con borde interno haciendo únicamente dos contactos (el pase y la recepción).\n\nNivel 1.- Se delimitará una zona de trabajo de 1 metro cuadrado, se colocarán dos o más jugadores en cada lado del ejercicio. En primer lugar se realiza el pase al compañero de enfrente con borde interno y se dirigirá hacia la parte de atrás del otro lado y así consecutivamente. El jugador debe controlar en la zona señalada y hacer de igual forma solo 2 contactos (pase y recepción).\n\nNivel 2.- Será el mismo ejercicio del nivel uno con distancias más largas, de igual forma con borde interno.\n\nNivel 3.- El mismo sistema del nivel uno, colocar conos en la parte frontal de la zona, y un cono en la mitad de los jugadores. El pase debe tener un poco de efecto pasando por al lado del cono y debe ingresar por el medio de los conos. Para que el pase tome el efecto el pase debe ser impactado con medio borde interno y con borde externo (tres dedos).","reglas":"Variantes: realizar repeticiones con pie izquierdo y derecho; utilizar para fines didácticos pases con punta, planta, taco; se puede utilizar en el nivel 2 pases con borde externo; se puede alternar: recepción pie izquierdo, pase pie derecho y viceversa; es importante abordar la autocorrección en este ejercicio para que el jugador tenga presente el desempeño de sus movimientos, de esta forma identifique si le ha salido bien para replicarlo y que corregir inmediatamente en la siguiente repetición.","observaciones":"","movimientosObservar":"Abrir bien el pie para el contacto con borde interno o interior; la recepción estrictamente debe ser con borde interno; enfatizar la precisión en la dirección del pase y la fuerza correcta entre las distancias; todo pase debe ser a ras de piso.","codigo":"PTÉC-11","id":"libro-11","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-11.jpg"},{"nombre":"Circuito de recepción y control","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"20","espacio":"4 metros de inicio a fin","duracion":"20","objFisico":"Sincronizar ojo, balón y superficie de recepción. Aumentar equilibrio al contacto con el balón. Afinar la velocidad y la fuerza para el tacto con el balón.","objTecnico":"Reconocer, aprender, repasar y perfeccionar la recepción de pases a ras de suelo, media altura y pases altos. Aplicar de forma correcta las superficies de contacto del cuerpo para controlar pases de todo tipo.","objTactico":"Asegurar el balón para la salida de juego. Mejorar la recepción a espaldas de los defensas.","objPsicologico":"Reconocer y aplicar la herramienta de Autorregulación. Incrementar los niveles de atención con los compañeros de equipo.","materiales":"balones, conos, cinta elástica (5 m), chalecos o petos, barreras","descripcion":"Circuito de recepción o control.- Recepción en amortiguamiento y dominio para controlar el balón.\n\nNivel 0.- El jugador se pondrá dentro de la zona marcada por las cintas o platos (1 metro\"), a 3 metros de distancia otro jugador enviará un pase a ras de piso, el balón debe quedar cercano al pie y acomodado para hacer el pase. Alterna pie derecho e izquierdo.\n\nNivel 1.- El mismo sistema del nivel 0, jugadores más distanciados, el pase debe ser más fuerte, alterna recepción pie izquierdo y pie derecho.\n\nNivel 2.- El mismo sistema del nivel 1, se coloca un cono al frente del jugador, jugador \"B\" envía un pase a media altura con la mano por encima del cono. El control se realizará con borde interno del pie (levantado la pierna y pie abierto) y con muslo. El balón debe quedar lo más cercano al pie.\n\nNivel 3.- El mismo sistema nivel 2, se coloca una barrera u obstáculo alto, amortiguamiento con pecho y control con pie.\n\nNivel 4.- El mismo sistema nivel 3, se coloca un jugador atrás que presionará e intentará quitar la pelota únicamente desde esa posición, el jugador recibirá pases a ras piso, media altura o alto, protegerá el balón con su cuerpo y brazos abiertos para mantener el equilibrio.","reglas":"Variantes: se puede colocar tres o más jugadores en el mismo ejercicio, lo óptimo es un balón por pareja; antes de pasar al nivel dos, se puede practicar recepción con planta, taco, borde externo; en el nivel 2, el jugador \"B\" puede dar el pase con el pie; con balón estático o que parta desde la mano y pie; en el nivel 3, se puede utilizar un jugador estático al frente del jugador que está trabajando; en el nivel 4, para generar competencia se contabilizarán las recepciones correctas entre todos los jugadores; la recepción también puede ser con salto, tanto para pecho, como para borde interno; explicar que para pases a ras de suelo se utiliza pie; media altura: pie, muslo, abdomen; pases altos: pecho.","observaciones":"","movimientosObservar":"La recepción debe ser dentro de su cuadrante; el pie debe estar bien abierto y levantarlo ligeramente del suelo para impactar en el centro del balón; enfatizar el equilibrio en el momento de pases a media altura, pases altos y con marcación; todos los jugadores deben pasar los niveles.","codigo":"PTÉC-12","id":"libro-12","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-12.jpg"},{"nombre":"Circuito de contacto con cabeza","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Iniciación","momentoJuego":"Defensa","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"20","espacio":"1 metro de inicio a fin","duracion":"17","objFisico":"Sincronizar ojo, balón y cabeza (frente). Aumentar fuerza en cuello y espalda para el impacto con el balón.","objTecnico":"Reconocer, aprender, repasar y perfeccionar despejes de cabeza en balones aéreos o altos. Aplicar de forma correcta el golpe de cabeza para realizar pases y definición.","objTactico":"Progresar los despejes con cabeza. Afinar la definición con cabeza","objPsicologico":"Generar automotivación. Incrementar la confianza y agresividad para decidir el impacto de cabeza en jugadas aéreas.","materiales":"balones, conos, chalecos o petos, cinta elástica (5 m), mini portería","descripcion":"Circuito de contacto con cabeza\n\nNivel 0. El jugador se colocará de rodillas detrás de una línea de referencia, recibirán el un pase con mano del jugador \"B\", el impacto debe ser con la frente, El modo más fácil de cabecear es colocar los brazos hacia adelante, en posición como si lo va a agarrar con la mano, en el momento que el balón se acerca, retira las manos hacia atrás y la cabeza hacia adelante. La devolución debe ser con golpe fuerte y con dirección a las manos del jugador \"B\".\n\nNivel 1.- El mismo sistema del nivel O, este caso lo van a hacer de pie.\n\nNivel 2.- El mismo sistema del nivel 1, aumenta la distancia entre los jugadores y la elevación del balón.\n\nNivel 3.- El jugador toma el balón en sus manos y lo lanza hacia arriba, impacta con cabeza para hacer gol en portería o mini portería que se encuentra en frente,\n\nEjercicio 2 (despeje con cabeza).- El entrenador enviará balones altos, como un saque de arquero, el jugador despejará con mucha fuerza. \nEjercicio 3 (definición con cabeza).- los entrenadores o jugadores, se colocan en la parte de atrás del arco o lateral simulando un centro. El jugador arranca desde un punto señalado de media cancha, recibe un balón aéreo y definirá con la cabeza haciendo gol en la portería resguardado por un portero.","reglas":"Variantes: se puede aplicar máximo tres jugadores con un balón; nivel 1, los dos jugadores pueden utilizar la cabeza, contabilizando los golpes, para generar competencia con el resto de las parejas o triadas; se recomienda crear las parejas con estatura similar; en el nivel 2, se puede saltar antes del impacto con la cabeza; con categorías menores a 12 años el balón debe estar con menos libras de presión para suavizarlo; en el ejercicio definición se contabilizan los goles para generar competencia.","observaciones":"","movimientosObservar":"Manos y brazos deben ir hacia atrás con fuerza; la cabeza debe impactar el balón; siempre impactar con la frente; el cuello siempre debe estar frontal al balón; el despeje debe ser con mucha fuerza; en la definición debe mirar rápidamente al arquero y portería antes de golpear con la cabeza.","codigo":"PTÉC-13","id":"libro-13","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-13.jpg"},{"nombre":"Circuito de conducción con balón","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Vacío","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"20","espacio":"15 metros de inicio a fin","duracion":"13","objFisico":"Sincronizar balón, espacio y control del balón con el pie. Aumentar resistencia aeróbica.","objTecnico":"Reconocer, aprender, repasar y perfeccionar la conducción del balón. Utilizar de forma correcta los diferentes contactos del pie para conducir en línea recta, zig zag y con obstáculos.","objTactico":"Aprovechar la salida en transiciones (contra golpes). Proyectar el ataque o transiciones con el balón controlado.","objPsicologico":"Reconocer la herramienta de autocontrol. Incrementar el sentido de observación panorámica con el balón.","materiales":"balones, conos, conos bajos o platos, estacas o picas","descripcion":"Circuito de conducción con balón.- el balón debe estar lo más pegado al pie todo el tiempo.\n\nEjercicio A.- Conducción con Giro 360% en los conos, alternando el sentido borde interno y externo del pie, llega al cono final y el retorna al inicio. En el trayecto recto se utiliza borde externo, realizar entre 8 y 10 contactos hasta el punto inicial.\n\nEjercicio B.- Inicia con conducción lineal borde externo, al llegar al círculo, conducción con planta del pie en la media circunferencia, giro en el cono 180%, en el retorno nuevamente conducción con planta por el interior de la semicircunferencia. Ejercicio C.- Conducción por las estacas verticales en eslalon, cambio de dirección de entrada y salida con borde externo del pie. Ejercicio D.- Conducción en zig zag, cambio de dirección con borde interno (enganche).\n\nEjercicio E.- Conducción aleatoria, borde interno, borde externo y planta en todo el trayecto, hacerlo en el menor tiempo posible.","reglas":"Variantes: el calentamiento antes del ejercicio debe ser un previo de la conducción; explicar al jugador la diferencia entre conducción y desplazamiento; se puede alternar repeticiones con pierna izquierda y pierna derecha; se puede hacer conducción rápida sobre cualquier línea recta de la cancha con todos los contactos del pie; si toca cualquier obstáculo con el balón deberá comenzar desde el principio; en el ejercicio \"E\" el trayecto puede ser improvisado pero siempre debe pasar por todos los obstáculos; el ejercicio \"C\" también se puede hacer con borde interno.","observaciones":"","movimientosObservar":"El pie debe estar siempre lo más cercano al balón; enfatizar que mientras más contacto tenga el pie con el balón la conducción va a tener mejor control; los cambios de dirección deben ser lo más rápido que el jugador pueda; el jugador identificará con que contacto del pie es más hábil en la conducción.","codigo":"PTÉC-14","id":"libro-14","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-14.jpg"},{"nombre":"Circuito de precisión","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"16","espacio":"10 metros de conducción y balón","duracion":"12","objFisico":"Mejorar los ritmos antes del pase. Ampliar la flexibilidad en tobillos.","objTecnico":"Reconocer, aprender, repasar y perfeccionar la precisión de pase y colocación. Utilizar de forma correcta los diferentes contactos del pie mejorando la precisión en definición","objTactico":"Asegurar el pase entre líneas. Afinar la eficiencia del último pase.","objPsicologico":"Generar la herramienta de autoconfianza. Elevar la motivación por el aumento de su técnica.","materiales":"balones, estacas o picas, conos, escaleras de coordinación, vallas, conos bajos o platos, barreras, cinta elástica (5 m)","descripcion":"Circuito de precisión.- El impacto al balón con borde interno, borde externo y empeine.\n\nEjercicio 1.- Los jugadores se colocan en el primer nivel, impactan el balón estático hacia la estaca que se encuentra al frente, si logra impactar a su objetivo subirá al nivel 2. En resumen, si logra tocar subjetivo con el balón subirá un nivel, si no lo hace bajará un nivel. Ganará el jugador que al terminar el tiempo del ejercicio se encuentre en el nivel más alto.\n\nEjercicio 2.- A) Conducción de balón en zigzag, definición del balón entre las picas o mini portería. B) Conducción en zigzag vertical y debe derribar el cono de enfrente. C) Se realiza un autopase, el balón pasa por un lado de la escalera del jugador por el otro, define a cualquier lado de la portería. D) Inicia con un autopase, el balón pasa por debajo de las vallas, el jugador se desplaza por cualquier lado y define hacia la estaca o cono de enfrente. E) el jugador conduce al rededor de los conos, intercambiando la dirección en cada uno y define con dirección a pica o mini portería.","reglas":"Variantes: en categorías menores a 12 años se pueden utilizar conos o balones; en categorías de 8 a 10 años se puede jugar bolos utilizando conos para que los derriben; se puede dividir al arco en 9 partes y el jugador deberá ingresar el balón por el agujero señalado; en categorías mayores a 12 años se puede jugar crossbar, impactando en los verticales y el horizontal del arco; cada acierto sumará puntos durante toda la tarea para generar competencia; indicar a los jugadores que la precisión sirve para pases, definiciones y tiros libres; se pueden practicar en rondas de penales, tiros libres con barrera y sin barrera.","observaciones":"","movimientosObservar":"Abrir bien el pie cuando se impacta con borde interno; cerrar bien el pie cuando es borde externo; inclinar bien el pie cuando el impacto es con empeine; se debe tomar más en cuenta la dirección del balón que la fuerza; incentivar al jugador con todos los contactos; trabajar en las debilidades de impacto en los jugadores.","codigo":"PTÉC-15","id":"libro-15","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-15.jpg"},{"nombre":"Control orientado en zonas","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"5","maxJugadores":"20","espacio":"6 metros entre jugadores","duracion":"15","objFisico":"Afinar los sentidos para mirar, decidir, ejecutar y apoyar. Adaptación de resistencia aeróbica.","objTecnico":"Reconocer, aprender, repasar y perfeccionar el control orientado. Aplicar de forma correcta los movimientos del cuerpo y orientación para agilizar el control orientado.","objTactico":"Mejorar y asegurar la salida de juego. Agilitar el movimiento del balón entre el equipo.","objPsicologico":"Iniciar la utilización de la herramienta auto entrenamiento. Concientizar el trabajo de equipo.","materiales":"balones, platos o conos bajos, chalecos o petos, cinta elástica (5 m)","descripcion":"Control orientado.- en zonas de trabajo y formación de equipo. Amortiguamiento en la recepción perfilándose al siguiente pase o jugada.\n\nEn zona.- Se formarán cuadrantes con platos o conos y se colocará un jugador en cada uno, el jugador del centro comenzará el ejercicio y entregará el balón a cualquiera de los 4 puntos. Los jugadores de afuera devolverán el balón lo más pronto posible únicamente al jugador de centro, posteriormente, recibirá con la pierna más alejada al pase haciendo un cambio de sentido inmediato, perfilándose y eligiendo el pase con la otra pierna a cualquiera de los otros 3 jugadores restantes.\n\nEn formación.- Se forma a todos los jugadores distribuidos en toda la cancha y en su posición de juego (juego de posición), se repite el ejercicio anterior (en zona), en este caso tiene más espacio para controlar y a su vez más alternativas de pase.","reglas":"Variantes: los jugadores de afuera pueden realizar la devolución con un solo toque; contar las repeticiones hechas correctamente dentro del tiempo; alternar en la marcha con pierna izquierda y pierna derecha; incentivar la creatividad del control orientado con planta del pie y taco; en el juego de posición, una vez establecidas las zonas de acción de cada jugador, podrá realizar controles cortos y largos, aprovechando el espacio. Siempre regresará al lugar de inicio; se pueden colocar jugadores que realicen marcación en sombra o real para que actúen todos.","observaciones":"","movimientosObservar":"La fuerza y precisión de todos los pases; máximo dos contactos (control y pase); si el pase inicial es correcto, la devolución también lo será; la utilización de las dos piernas; la decisión del siguiente pase mientras el balón está en camino.","codigo":"PTÉC-16","id":"libro-16","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-16.jpg"},{"nombre":"Circuito de remate","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Finalización","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"20","espacio":"10 metros de conducción y balón","duracion":"15","objFisico":"Afinar la orientación y el perfil. Aumentar la fuerza en piernas y estómago.","objTecnico":"Reconocer, aprender, repasar y perfeccionar la fuerza y dirección del remate. Utilizar de forma correcta los diferentes contactos del pie para golpear el balón con fuerza.","objTactico":"Despejar con fuerza. Mejorar los tiros de media distancia.","objPsicologico":"Crear herramientas de auto superación. Generar agresividad al golpear el balón.","materiales":"balones, estacas o picas, conos bajos o platos, vallas, escaleras de coordinación, aros o anillos, barreras","descripcion":"Circuito de remate.- se debe utilizar empeine en el contacto con el balón y con mucha fuerza.\n\nEl jugador deberá rematar el balón lo más fuerte posible en dirección hacia el arco, aplicando nuevamente el ejercicio de precisión. En la portería se colocarán vallas y una barrera que simularán un portero. El trayecto es sin balón.\n\nEjercicio A.- Conducción con el balón en eslalon con vallas verticales y remate con cuerpo y pierna perfilada al arco\n\nEjercicio B.- El jugador salta las vallas con piernas juntas y finaliza con remate.\n\nEjercicio C.- El jugador pasa por la escalera en coordinación (uno o dos contactos en los espacios), posteriormente ejecutar el remate. Ejercicio D.- El jugador salta entre los aros alternando pierna izquierda y derecha con zancadas largas, remate al arco.\n\nEjercicio E.- El ejercicio es con velocidad, después del primer plato se desplaza a la izquierda de frente, retrocede al mismo plato, después se dirige hacia el plato derecho, retrocede nuevamente al primer crono y se impulsa con fuerza para hacer el remate final.","reglas":"Variantes: los trayectos sin balón deben hacerse a velocidad, los saltos deben ser altos y rápidos; se puede hacer con conducción de balón y posteriormente remate. Desde todos los perfiles; se pueden hacer remates desde distancias lejanas al arco con balón estático; se puede practicar el saque de arco, con balón estático desde el área de defensa hasta el otro arco; se puede aplicar el despeje desde el área de la defensa con pelota en movimiento o con bote; los remates pueden ser a ras de suelo, media altura y altos. 7,- Se puede colocar uno o varios porteros para bloquear los remates.","observaciones":"Etapa o día recomendado: -3","movimientosObservar":"El remate debe ser con el empeine en el centro del balón; se debe enfatizar la fuerza en pierna y estómago; el perfil y orientación del cuerpo y pierna; el pie de apoyo debe estar lo más cerca al balón; el equilibrio con los brazos abiertos, especialmente el brazo contrario a la pierna que remata.","codigo":"PTÉC-17","id":"libro-17","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-17.jpg"},{"nombre":"Circuito de dribling o regate","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Vacío","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"6","maxJugadores":"14","espacio":"10 metros de inicio a fin","duracion":"15","objFisico":"Aumentar la reacción en los cambios de sentido. Intensificar la velocidad en movimientos.","objTecnico":"Reconocer, aprender, repasar y perfeccionar el dribling o regate. Utilizar de forma correcta los movimientos para avanzar con dribling líneas defensivas.","objTactico":"Asegurar la salida en acumulación de jugadores. Avanzar líneas y superar adversarios especialmente 1 contra 1.","objPsicologico":"Refuerza la autorregulación. Iniciar o elevar la creatividad en movimientos.","materiales":"balones, conos bajos o platos, estacas o picas, conos, cinta elástica (5 m), chalecos o petos","descripcion":"Circuito de dribling o regate.- avanzar líneas y mantener el balón de forma individual. Engaño en espacios cortos y rápidos.\n\nNivel 0.- El jugador hace una trayectoria hacia el cono y cambia de dirección rápidamente, entrega el balón al compañero que se encuentra al frente se coloca en la parte de atrás de la columna esperando nuevamente su turno.\n\nNivel 1.- El mismo sistema nivel 0, a la altura de la estaca o pica, el jugador amaga ir para un lado y avanza por el otro lado, lo mismo en la siguiente estaca o pica.\n\nNivel 2.- Cuatro o más jugadores por estación. Comienza el jugador \"B\" que se encuentra en el centro, entrega con un pase al jugador \"A\" y se dirige a donde el jugador \"B\" y realiza un engaño calculando tiempo, velocidad y distancia. Jugador \"B\" sólo hará marcación en sombra y se dirige al punto de partida del jugador \"A\",\n\nNivel 3.- Se forma un mini campo con cintas elásticas (6 m x 4 m), se definen 2 mini porterías, en el espacio actuarán 1 contra 1, cada uno defenderá su portería. Para hacer goles el jugador deberá driblar a su rival en conducción por la línea de meta, si esto ocurre, dejará el balón cerca a la línea y regresará a defender inmediatamente. Si el balón sale por la parte lateral, comenzará desde la portería.","reglas":"Variantes: realizar una demostración de todos los tipos de dribling; aplicar todos los tipos de dribling en los tres primeros niveles: autopase, gambeta, bicicleta, carrusel, elástica, túnel, sombrerito, etc; practicar el cambio de sentido con planta en los primeros dos niveles. Izquierda y derecha; el cambio de sentido debe hacerse preferiblemente con borde externo. Izquierda y derecha; nivel 3, se puede actuar en postas. Siempre un jugador dentro de la mini cancha; se puede organizar un torneo rápido entre todos los jugadores dentro de un mini partido.","observaciones":"Etapa o día recomendado: Tercer o cuarto día.","movimientosObservar":"Para que exista engaño, el sentido del cuerpo debe ir a un lado y el balón en sentido contrario; el control de la velocidad en el momento de acercarse al obstáculo a evadir; el pie debe estar siempre pegado al balón; precisar espacios y tiempos antes de acercarse al obstáculo.","codigo":"PTÉC-18","id":"libro-18","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-18.jpg"},{"nombre":"Circuito de enganche o recorte","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"14","espacio":"12 metros de trayecto","duracion":"8","objFisico":"Aumentar la decisión en los cambios de orientación. Fortalecer tren inferior y agilidad en cintura.","objTecnico":"Reconocer, aprender, repasar y perfeccionar el enganche en cambio de ritmos y direcciones. Utilizar de forma correcta los movimientos de enganche para engañar y superar defensas.","objTactico":"Generar eficiencia en desdobles laterales. Engañar para tener libertad de remate o definición.","objPsicologico":"Refuerza la autocorrección. Activar el rediseño de decisiones.","materiales":"balones, estacas o picas, conos, barreras, cinta elástica (5 m)","descripcion":"Circuito de enganche.- Es un tipo de dribling o regate que consiste en utilizar el borde interno del pie para cambiar la dirección brusca del balón o detenerlo.\n\nEjercicio A.- Forma triangular, conducción continua en sentido horario y contra horario para utilizar dos perfiles. Enganche a 60\". Ejercicio B.- Forma cuadrada, enganche a 90 grados, con pierna izquierda y pierna derecha.\n\nEjercicio C.- Enganche en zigzag con estacas o picas.\n\nEjercicio D.- El jugador conduce de forma aleatoria, al encontrar un obstáculo realiza el enganche ya sea por la izquierda o la derecha. Realizará la mayor cantidad en un tiempo determinado.","reglas":"Variantes: calentamiento previo con bordes internos, pie izquierdo, pie derecho y simultáneos; también se puede hacer en eslalon vertical con estacas; si toca cualquier obstáculo con el balón, deberá repetir el ejercicio; para categorías mayores de 16 años se pueden hacer todos los ejercicios en un solo trayecto en varias series para trabajar resistencia; los enganches también se pueden practicar con un jugador que realice marcación sombra, alternando las funciones.","observaciones":"Etapa o día recomendado: Cuarto día.","movimientosObservar":"Trayecto recto con borde externo del pie y pegado al balón (conducción); debe cambiar de sentido en un solo toque y acomodar al siguiente trayecto; la pierna de enganche debe poseer debe estar lo más extendida, la pierna de apoyo debe flexionarse y generar equilibrio.","codigo":"PTÉC-19","id":"libro-19","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-19.jpg"},{"nombre":"Circuito de definición","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Finalización","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"6","maxJugadores":"12","espacio":"4 metros de conducción y remate","duracion":"12","objFisico":"Afinar los ritmos, las distancias, las orientaciones y los perfiles para una correcta definición. Controlar las velocidades y frenos en definición.","objTecnico":"Reconocer, aprender, repasar y perfeccionar la definición. Utilizar de forma correcta la conducción, contactos y dribling para mejorar la definición.","objTactico":"Efectivizar los desdobles. Aumentar la efectividad de ataques para que terminen en gol.","objPsicologico":"Subir niveles de autoconfianza. Identificar responsabilidad y aumentar creatividad.","materiales":"balones, estacas o picas, conos","descripcion":"Circuito de definición.- Siempre se lo realiza en el área con portero en situación real.\n\nSe conduce con velocidad en línea recta desde tres cuartos del campo, se alterna el ingreso al área desde el carril central, el carril central izquierdo y el carril central derecho.\n\nLos conos y las estacas son referencias por donde el jugador deberá ingresar al área y definir con borde interno, borde externo o empeine dando la dirección y fuerza precisa al lugar que encuentre espacio y concrete goles. El portero debe salir achicando espacios de portería perfilándose de acuerdo a lado que le están atacando, siempre partirá desde el centro de la portería.","reglas":"Se pueden colocar obstáculos cortos en la conducción, antes de la definición; se puede hacer un pase largo, alto para controlar antes de entrar al área y definir; la definición puede ser afuera del área, dentro del área o con dribling al portero; puede haber marcación sombra o real de un defensa para generar presión psicológica, así como un tiempo límite; antes de la definición deberá resolver alguna operación matemática o responder alguna pregunta de cultura general, de esta forma se sistematiza instintivamente el movimiento anterior a la definición.","observaciones":"Definición a primer palo escuadra o arriba. Definición a segundo palo escuadra de abajo.","movimientosObservar":"El perfil y la orientación hacia la portería; la elección de la pierna y la superficie de contacto del pie; la velocidad y distancias del arquero; mirar rápidamente al arquero y la portería antes de la definición; decisión y seguridad en toda la jugada.\n\nLa toma de decisión en la técnica de definición del jugador debe ser antes de llegar al área del portero.","codigo":"PTÉC-20","id":"libro-20","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-20.jpg"},{"nombre":"Estaciones de anticipación","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Iniciación","momentoJuego":"Defensa","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"16","espacio":"8 metros de inicio a contacto","duracion":"16","objFisico":"Agudizar la reacción en la jugada. Potenciar la fuerza de deslizamiento y velocidad de reacción.","objTecnico":"Reconocer, aprender, repasar y perfeccionar los movimientos de anticipación y entrada. Utilizar de forma correcta la técnica de entrada (barrida) y desarrollar el sentido de anticipación.","objTactico":"Aumentar la eficiencia de destruir jugadas de avance del adversario y apoderarse del balón. Ganar más balones en zona de creación y defensa para transiciones ofensivas.","objPsicologico":"Utilizar la herramienta de auto conducta. Incrementar agresividad para recuperar el balón.","materiales":"balones, conos bajos o platos, conos, estacas o picas, vallas, aros o anillos, chalecos o petos","descripcion":"Estaciones de Anticipación.- con entrada (barrida) y carga (contacto corporal), pierna izquierda y derecha. Apoderarse o desviar el balón. Nivel 1. El entrenador envía el balón hacia los platos el jugador desde su marca irá al encuentro del balón. Aprende la adaptación, reconocimiento de velocidad-espacio y fuerza al contacto con el balón.\n\nNivel 2 - El mismo sistema del nivel 1, esta vez el jugador deberá pasar por alguno de los dos lados de la valla, en lo posible apoderarse del balón.\n\nNivel 3.- El jugador hará el mismo movimiento nivel 2, en este caso deberá esforzarse o hacer una barrida para anticipar el balón antes que toque el cono.\n\nNivel 4.- Se extiende la zona de cobertura para simular que el jugador que va a recibir el balón también está haciendo una barrida, el jugador deberá anticipar antes de que llegue el balón al cono.\n\nNivel 5. - Se coloca un jugador que reciba el balón y abrirá los brazos protegiéndose, el otro jugador deberá anticipar antes de que el balón llegue a quien está trabajando la zona del centro.","reglas":"La distancia del pase de inicio, también puede ser iniciado por un jugador para después intercambiar roles; la distancia de anticipación puede ser más corta, a un metro del obstáculo o jugador; el pase puede ser a media altura y alto; la anticipación y la entrada se debe alternar por los lados izquierdo y derecho; la entrada debe ser únicamente en pases a ras de suelo, alternando pierna izquierda y derecha; se puede practicar en la zona de la posición de cada jugador para familiarizar y afianzar su confianza.","observaciones":"","movimientosObservar":"La velocidad y fuerza de entrada; la entrada únicamente con una sola pierna; una pierna extendida y la otra flexionada hacia atrás para proteger la fricción; el brazo abierto para amortiguar la caída; el jugador debe levantarse lo más rápido posible después de la acción, aprovechando el impulso.","codigo":"PTÉC-21","id":"libro-21","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-21.jpg"},{"nombre":"Estaciones de interceptación","categoria":"Técnico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Iniciación","momentoJuego":"Transición defensiva","tipoTarea":"","edad":"Todas las categorías","minJugadores":"6","maxJugadores":"16","espacio":"3 y 6 metros de inicio a contacto","duracion":"15","objFisico":"Mejorar el equilibrio al contacto con otro jugador. Intensificar la velocidad de reacción.","objTecnico":"Reconocer, aprender, repasar y perfeccionar los movimientos de interceptación y carga. Utilizar de forma correcta la técnica de carga y desarrollar el sentido de interceptación.","objTactico":"Agudizar el sentido de vigilancia. Aumentar la eficiencia de interceptar jugadas en zona de creación y finalización.","objPsicologico":"Reforzar la auto conducta. Afinar la aplicación de atención en jugadas.","materiales":"balones, conos bajos o platos, conos, chalecos o petos, cinta elástica (5 m)","descripcion":"Estaciones de interceptación.- Apoderamiento o desviación del balón.\n\nNivel 1.- El jugador se colocará en la marca inicial en el centro de los conos, el entrenador realizará pases a los conos y el jugador interceptará el pase durante la trayectoria.\n\nNivel 2.- El jugador puede ubicarse en cualquiera de las dos marcas de inicio, del entrenador realizará pases a cualquiera de los cuatro conos el jugador con reacción rápida interceptará en la trayectoria del balón.\n\nEjercicio 3 (carga).- Un jugador se colocará en una zona delimitada por platos, conos o cintas. Otro jugador que coloca atrás esperando el pase, cuando el jugador de la zona reciba el balón, realizar a una carga con pecho, estómago o piernas. El propósito del ejercicio es que el jugador se acostumbre a tener contacto, tanto para quitar el balón como para protegerlo.","reglas":"Ampliar el ángulo y la distancia del jugador cuando haya dominado el nivel 1; el nivel 2 se puede trabajar individualmente o en pareja, para sincronizar movimientos por zonas; también se puede aplicar entrada (barrida) en la interceptación; el pase también puede ser a media altura y alto; si la interceptación es correcta y existe apoderamiento de balón, el jugador puede avanzar y hacer un gol en las mini porterías laterales para incentivar la transición ofensiva; en la carga únicamente pases a ras de piso y media altura.","observaciones":"","movimientosObservar":"Generar el instinto del ejercicio al jugador; el arranque debe ser rápido; el riesgo de abandonar su zona de cobertura; recuperación inmediata si la acción es fallida; en la carga, brazos abiertos para mejorar el equilibrio y piernas ligeramente flexionadas para bajar el centro de gravedad.","codigo":"PTÉC-22","id":"libro-22","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-22.jpg"},{"nombre":"Zonas del campo","categoria":"Táctico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"30 x 15 metros (cancha completa)","duracion":"24","objFisico":"Agudizar movimientos y desplazamientos con sincronización y ritmo. Amplificar la resistencia aeróbica.","objTecnico":"Observar e identificar las zonas y fases donde se fundamenta la defensa. Observar e identificar las zonas y fases donde se progresa y se crea el ataque.","objTactico":"Reconocer, aprender y dominar las zonas del campo y las fases de progresión de las jugadas. Desarrollar y progresar el fundamento táctico de ubicación en campo para defensa, salida y progresiones.","objPsicologico":"Empezar a reconocer la herramienta de auto entrenamiento. Intensificar los sentidos para una mejor atención y concentración.","materiales":"balones, cinta elástica (5 m), chalecos o petos","descripcion":"ZONAS.- Se divide al campo de juego o a la cancha con las cintas elásticas en 9 zonas como forma la figura, se explica a los jugadores cada una de ellas. Con orientación frontal de ataque se explica en donde se encuentra la zona o carril central y las zonas laterales o bandas: el izquierdo y el derecho.\n\nDistribuimos a los jugadores en todo el campo y tomarán su posición de juego. El portero siempre comenzará la jugada con las instrucciones del entrenador, pasando el balón por todas las zonas hasta que todos los jugadores reconozcan todas las zonas. FASES.- Se divide el campo en 3 fases con cintas transversales. La primera fase defensiva o inicial, la siguiente zona del medio campo o creación y la tercera zona de ataque o de finalización. De la misma manera se colocan a los jugadores de acuerdo a su posición de juego, el arquero iniciará la jugada con el balón, qué pasará por cada unos de los jugadores. El entrenador indicará por cual de las zonas deberá transitar el balón para explicar detalladamente los fundamentos de cada una de ellas.","reglas":"Llevar a todos los integrantes del equipo a la zona o fase señalada para un mejor reconocimiento; en el caso de que el balón salga del campo se reiniciará siempre desde el portero; se puede colocar un equipo o algunos jugadores adversarios para que realicen marcación en sombra o real; después de pasar el balón por todos los jugadores, zonas y fases la jugada termina en gol; se pueden diseñar jugadas para que se pueda interactuar en las diferentes zonas y fases.","observaciones":"","movimientosObservar":"Los jugadores deben tener total atención; antes de comenzar el ejercicio con balón todos los jugadores deben reconocer las zonas y las fases con los ojos cerrados; poner énfasis en la precisión de pase, recepción y perfil en los jugadores.","codigo":"PTÁC-23","id":"libro-23","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-23.jpg"},{"nombre":"Modos o momentos del juego","categoria":"Táctico","tipoEjercicio":"Ejercicio sistémico","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Vacío","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"30 x 15 metros (cancha completa)","duracion":"25","objFisico":"Potenciar movimientos y desplazamientos con reacción y orientación. Incrementar la resistencia aeróbica intensiva.","objTecnico":"Identificar y practicar los modos o momentos para fundamentar la defensa. Identificar y practicar los modos o momentos para fundamentar el ataque.","objTactico":"Reconocer, aprender y dominar los modos o momentos que suceden en el desarrollo de un partido. Desarrollar y progresar los fundamentos tácticos de comportamiento en defensa y ataque.","objPsicologico":"Ganar experiencia utilizando caracteres de autorregulación. Repasar el sentido de sacrificio en el trabajo de equipo.","materiales":"balones, cinta elástica (5 m), chalecos o petos","descripcion":"MODOS O MOMENTOS DEL JUEGO.- Se divide al campo de juego o cancha con las cintas en 9 partes, diferenciando las diferentes zonas y fases.\n\nModo defensa. - El portero del equipo \"A\" comenzará la jugada, se posicionarán a los jugadores como muestra la figura, la formación debe cubrir la zona central con distancias cercanas (formación cerrada).\n\nModo ataque.- Iniciará la jugada el portero del equipo \"B\", los jugadores se colocarán en su posición de juego, la formación abarca las zonas centrales y laterales con distancias alargadas (formación abierta).\n\nModo transición defensiva.- Se realiza un inicio de ataque y se simula que el jugador del equipo ha perdido el balón en la zona del rival, los jugadores más próximos al balón deberán cerrar los espacios, los demás realizan un repliegue para reforzar la defensa.\n\nModo transición ofensiva o ataque.- Se coloca al equipo en formación modo defensivo y simulamos que recuperamos del balón en la zona de creación o inicial, inmediatamente los jugadores tomarán posición de avance o proyección en ataque.","reglas":"La primera explicación debe ser sin balones, para una mejor comprensión; el modo ataque comienza únicamente cuando el balón inicie desde el porter y con balón parado; el modo defensa comienza únicamente cuando el balón inicie desde el arquero del equipo contrario y con balón parado; las transiciones ofensivas pueden practicarse con avance elaborado o directo, es decir conservando el balón haciendo la mayor cantidad de pases o contragolpe con pocos pases y largos; las transiciones defensivas pueden practicarse con presión al adversario tras la pérdida.","observaciones":"","movimientosObservar":"P- Movimientos, perfiles y desplazamientos correctos de acuerdo a la posición del balón; atención y concentración en cada uno de los jugadores; desplazamientos rápidos y ordenados; comunicación firme y alta para que se pueda escuchar en toda el campo de juego.","codigo":"PTÁC-24","id":"libro-24","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-24.jpg"},{"nombre":"Estación de desmarque","categoria":"Táctico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Finalización","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"20 metros de inicio a fin","duracion":"15","objFisico":"Reconocer ritmos y espacios temporales para realizar desmarques. Adaptarse a ritmos intensos y ritmos de descanso cortos.","objTecnico":"Reconocer los desplazamientos que existen en el desmarque y apoyo. Desarrollar y progresar los fundamentos tácticos de desmarque de apoyo y ruptura en ataque.","objTactico":"Distinguir los movimientos y desplazamientos de desmarque para reforzar la zona defensiva. Ampliar el conocimiento y utilización de desmarque para generar espacios en el ataque.","objPsicologico":"Utilizar autocorrección para mejorar las jugadas. Observar el recurso y concepto de apoyo con sus compañeros.","materiales":"balones, conos bajos o platos, chalecos o petos","descripcion":"Estación de desmarque.- En el primer ejercicio se coloca tres jugadores por estación, el objetivo del jugador \"A\" es pasar a ras de piso el balón al jugador \"B\", el defensa del centro (jugador rojo) deberá bloquear o interceptar entre estos dos jugadores, sólo actuará dentro de la zona de los platos de frente al jugador \"A\". El jugador \"B\" debe realizar movimientos de desmarque a la espalda del defensa para recibir el balón de forma libre, su recorrido será semicircular únicamente por afuera de los platos. Circuito de desmarque.- En el segundo ejercicio el jugador \"A\" pasará el balón hacia jugadores \"B\". El jugador \"B\" iniciará en el plato rojo y estará marcado con un defensa en su espalda quien lo seguirá en sus movimientos (acoso). El jugador \"B\"\" decidirá si realiza el movimiento hacia el plato verde y recibiendo el balón, haciendo un desmarque de apoyo. También, puede decidir si realiza un desmarque de ruptura, pasando por los platos amarillos evadiendo la marca del defensa y ganando sus espaldas. El jugador \"A\" en este caso realizará un pase a profundidad, si esto sucede, se acercará al área para recibir el pase centro y definir en portería.","reglas":"El jugador \"A\" puede realizar pases con izquierda y con derecha; el jugador \"B\" puede devolver el balón en un solo contacto; el jugador \"B\" puede devolver el balón en dos contactos, recepción y pase; alternar la jugada en izquierda y derecha en el circuito para que el jugador pueda perfilarse y orientarse desde los dos carriles laterales; el centro antes de la definición también puede ser a media altura y alto; se puede colocar un defensa en marcación sombra o real para que exista desmarque en definición.","observaciones":"","movimientosObservar":"El jugador que se desmarca debe engañar su trayectoria; debe señalar en qué lugar desea el balón con la mano o con movimientos corporales; marcar los tiempos del pase corto o largo; el pase debe ser preciso a ras de piso o media altura con bote a favor del receptor.","codigo":"PTÁC-25","id":"libro-25","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-25.jpg"},{"nombre":"Presión (pressing) en juego de posición","categoria":"Táctico","tipoEjercicio":"Ejercicio sistémico","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Vacío","momentoJuego":"Defensa","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"30 x 15 metros (campo completo)","duracion":"16","objFisico":"Utilizar correctamente los tiempos y espacios de pressing. Adaptarse a ritmos intensos y ritmos de descanso cortos.","objTecnico":"Mirar y dominar las distancias y fases para recuperar el balón. Recuperar el balón lo más pronto posible al perderlo.","objTactico":"Reconocer, aprender, repasar y perfeccionar el pressing o niveles de presión para recuperar el balón. Reforzar los fundamentos tácticos de pressing para provocar error en el rival.","objPsicologico":"Utilizar cualidades de autoconducta para ganar el balón. Aumentar el sentido de agresividad a la jugada para recuperar el balón.","materiales":"balones, cinta elástica (5 m), chalecos o petos","descripcion":"Se divide el campo con líneas longitudinales y transversales, dividiendo a la cancha en nueve zonas (juego de posición).\n\nEjercicio \"A\".- Todos los jugadores se colocaran en formación, modo defensa, señalando que sería la posición de marcación en presión baja.\n\nEjercicio \"B\".- La misma posición del ejercicio anterior, adelantamos las líneas con las mismas distancias, el arquero se adelanta hasta el punto penal. Indicar al equipo que es la posición de marcación en presión media.\n\nEjercicio \"C\".- Se adelanta las líneas con las mismas distancias, los delanteros haciendo cobertura a centrales, el portero casi al borde del área atento a despejar o interceptar balones largos. Se demuestra al equipo que esa es la presión de marcación alta.","reglas":"En modo defensa o presión todos los jugadores deben estar cerrados, tomando en relación las líneas longitudinales; realizar varias repeticiones sin balón adelantando y retrocediendo para automatizar el movimiento de todos los jugadores; se puede colocar un equipo contrario que avance con el balón para alternar los tipos de pressing; se puede realizar partido condicionado aplicando los tres tipos de pressing.","observaciones":"","movimientosObservar":"Las líneas deben mantener siempre las mismas distancias; los jugadores deben mantener las mismas distancias; motivar para que todos los jugadores realicen desplazamientos rápidos; cuidar los perfiles de cada jugador; utilizar cualidades de autoconducta para ganar el balón.","codigo":"PTÁC-26","id":"libro-26","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-26.jpg"},{"nombre":"Rondo con apoyos y comodines exteriores","categoria":"Táctico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Iniciación","momentoJuego":"Defensa","tipoTarea":"","edad":"Todas las categorías","minJugadores":"","maxJugadores":"","espacio":"12 x 15 metros, campo reducido.","duracion":"11","objFisico":"Ampliar las habilidades de sincronización individual y en equipo. Mantener un ritmo cercano a umbral.","objTecnico":"Distinguir los movimientos y posiciones que permiten conservar el balón para la salida. Conservar e incrementar la posesión del balón en ataque.","objTactico":"Reconocer, aprender, repasar y perfeccionar tipos de amplitud, apoyo y opciones de pase en salida de balón. Aplicar y reforzar los fundamentos tácticos de apoyo, opciones de pase en progresión elaborada con balón.","objPsicologico":"Utilizar habilidades de autorregulación para conservar el balón. Aumentar el sentido de confianza del trabajo en equipo.","materiales":"balones, cinta elástica (5 m), chalecos o petos","descripcion":"Ejercicio A.- Se arma un cuadrante para realizar un rondo con apoyos, se conforman equipos de cuatro personas. Se colocan cuatro jugadores exteriores que serán comodines, los otros dos equipos en el medio de zona. Los equipos de adentro realizarán la mayor cantidad de pases apoyándose entre su equipo y con los comodines que se encuentran afuera. El otro equipo deberá quitar o interceptar los pases.\n\nEjercicio B.- Se colocan líneas longitudinales para diferenciar las zonas centrales y laterales. Se coloca a los jugadores en formación de acuerdo a su posición de juego (alineación). El arquero comenzará la jugada y se pasarán entre ellos de acuerdo con las líneas de pase señaladas. Se colocará un equipo contrario que realizará marcación sombra. Cuando el equipo pierda el balón siempre se reinicia desde el portero. Al realizar 20 pases seguidos, estará habilitado para hacer el gol en la portería contraria.","reglas":"El jugador puede realizar máximo dos contactos; ejercicio \"A\" el equipo que realice 15 pases obtiene un gol; ejercicio \"A\" el equipo que realice 60 pases gana, los pases son acumulativos si pierde el balón; se puede utilizar un comodín central para que juegue con el equipo que tiene el balón y generar superioridad numérica en esa zona; ejercicio \"B\" el jugador debe hacer máximo dos contactos; el equipo contrario puede hacer cualquier nivel de pressing real.","observaciones":"","movimientosObservar":"Pases precisos a ras de piso; recepciones o controles limpias; controles orientados rápidos; la fuerza del balón; el pase siempre al jugador libre o desmarcado; definición correcta; constancia y paciencia en la jugada.","codigo":"PTÁC-27","id":"libro-27","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-27.jpg"},{"nombre":"Marcación y basculación defensiva","categoria":"Táctico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Iniciación","momentoJuego":"Transición defensiva","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"20 metros de inicio a fin","duracion":"8","objFisico":"Afinar movimientos de equilibrio y orientación defensiva. Elevar resistencia aeróbica intensiva.","objTecnico":"Aumentar la seguridad de desplazamientos y orden defensivo. Desarrollar el sentido de equilibrio de jugadores entre defensa y ataque.","objTactico":"Reconocer, aprender, repasar y perfeccionar las distancias, temporizaciones y marcaje en equipo. Reforzar los fundamentos tácticos de coberturas defensivas.","objPsicologico":"Utilizar autocorrección para aprender de errores. Aumentar el sentido de responsabilidad en la zona y en los modos o momentos del juego.","materiales":"balones, cinta elástica (5 m), chalecos o petos","descripcion":"Ejercicio A.- Marcación en superioridad numérica. Se colocan 4 jugadores vs 3 atacantes, cada uno tomará la marca constante de un contrario para que el defensa central (#2) siempre quede libre. Comenzará la jugada del mediocampista del equipo rival que avanzará individualmente o en equipo para hacer el gol. El central deberá salir a la marcación siempre y cuando alguno de sus compañeros sean superados y corregir la jugada.\n\nEjercicio B.- Marcación en igualdad numérica. Se simula que el equipo rival tiene 4 atacantes versus 4 defensas. El lateral derecho(+4) está bloqueando la avance lateral del jugador con el balón, el mediocampista (5) toma la marca del otro rival, el defensa central (#2) con el delantero y el jugador 3 realizará una basculación conservando las distancias y vigilancia del jugador que viene por sus espaldas. Repetir el ataque por el lado contrario.\n\nEjercicio C.- Marcación en inferioridad numérica. El equipo rival (azul) tiene el control del balón y en proyección al arco, los dos jugadores deberán temporizar dentro de la zona marcada, deteniendo el avance el tiempo máximo, guardando distancias y vigilantes a los laterales hasta que se sume a la marca el mediocampista (rojo) que se repliega lo más pronto posible para presionar al jugador que posee el balón. El portero siempre atento a los pases entre líneas o en profundidad para interceptar el balón.","reglas":"colocar la línea defensiva con el número de jugadores deseados, designar zonas de responsabilidad de marcaje y distancias; los avances pueden ser realizados desde todas las zonas, con pases largos, pases cortos y conducción; identificar las zonas donde la defensa en inferioridad numérica debe cerrarse y volverse fuerte; repetir las tareas hasta que los movimientos se encuentren sistematizados; se puede practicar la táctica de fuera de juego como último recurso; se puede sumar al marcaje la línea de mediocampistas.","observaciones":"","movimientosObservar":"Las distancias continuas especialmente en la basculación; la recuperación del balón en superioridad numérica; la destrucción de la jugada lo más lejano al arco; repliegue y apoyo a la marcación veloz; reconocimiento de zonas vulnerables.","codigo":"PTÁC-28","id":"libro-28","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-28.jpg"},{"nombre":"Vigilancia y repliegue","categoria":"Táctico","tipoEjercicio":"Ejercicio sistémico","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Iniciación","momentoJuego":"Transición defensiva","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"40 x 60 metros (campo completo o disponible)","duracion":"20","objFisico":"Aumentar los sentidos de ritmo y reacción ante las jugadas. Adaptarse a resistencia mixta.","objTecnico":"Agudizar técnicas para la rápida recuperación de balón y reestructura defensiva. Reforzar los fundamentos tácticos de vigilancia en ataque y zonas de repliegue.","objTactico":"Reconocer, aprender, repasar y perfeccionar la vigilancia y el repliegue ante ataques directos. Reforzar los fundamentos tácticos de vigilancia en ataque y zonas de repliegue.","objPsicologico":"Aplicar la responsabilidad del autoentrenamiento fuera y dentro de la cancha. Intensificar el sentido de sacrificio y responsabilidad para obtener resultados.","materiales":"balones, chalecos o petos, cinta elástica (5 m)","descripcion":"Prácticas de vigilancia y repliegue en ejercicios sistemáticos.- Estar vigilantes y atentos de la estructura del equipo contrario para cuando el equipo pierda el balón en modo ataque o transición ofensiva para replegar o retroceder lo más ordenado y rápido a la portería.\n\nEjercicio A.- Se forma al equipo en posición de ataque y después de varios toques se paraliza el juego y se relaciona la posición del equipo versus la posición del equipo contrario para que los jugadores que no se encuentran en la acción de la jugada estén vigilantes de los jugadores libres y de las zonas vulnerables en caso de perder el balón. Se simula perder el balón en cualquier parte de la fase de finalización, cada jugador realizará su desplazamiento de repliegue a su puesto inicial.\n\nEjercicio B.- Muy similar al ejercicio A, en este caso los jugadores al simular la pérdida del balón, replegarán a una formación cerrada con relación a la línea transversal donde se encuentra el balón.","reglas":"El entrenador decide en qué momento se realiza el repliegue; se debe realizar movimientos de ataque por todas las zonas posibles; se debe reconocer la cobertura de inicio sin balón para el momento de repliegue; se debe designar los jugadores que actuarán en vigilancia antes, durante y después de la jugada; se puede practicar repliegue a la línea del balón, o a zonas media y baja; se practicar con un equipo contrario en partidos condicionados.","observaciones":"","movimientosObservar":"Repliegue en velocidad; todos los jugadores debe realizar marcación a un rival o a una zona durante el repliegue; cuidar los perfiles y orientación de avance y repliegue; los desplazamientos laterales y de espalda.","codigo":"PTÁC-29","id":"libro-29","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-29.jpg"},{"nombre":"Coberturas, repliegue y acoso","categoria":"Táctico","tipoEjercicio":"Ejercicio sistémico","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Vacío","momentoJuego":"Defensa","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"40 x 60 metros (campo completo o disponible)","duracion":"21","objFisico":"Aumentar la adaptabilidad de escenarios en cobertura homogénea o mixta. Desarrollar por medio del desplazamiento una capacidad de trabajo aeróbico y mixto.","objTecnico":"Utilizar coberturas para impedir la circulación del balón por zonas estratégicas. Elevar el porcentaje de recuperación de balones en zonas altas y centrales.","objTactico":"Reconocer, aprender, repasar y perfeccionar los movimientos correctos para realizar una buena cobertura. Reforzar los fundamentos tácticos de coberturas utilizando acoso y permutas.","objPsicologico":"Trabajar en caracteres de autoconfianza para lograr objetivos personales y grupales. Inculcar el sentido de solidaridad y corresponsabilidad en situaciones de equipo.","materiales":"balones, chalecos o petos","descripcion":"Ejercicio A.- Se colocan líneas longitudinales para diferenciar las zonas centrales y laterales. Se arma al equipo en formación de ataque y realizamos un ataque desde el portero hasta avanzar a la zona de finalización, se simula que el balón se pierde en cualquier parte del campo y los jugadores regresaran al puesto más cercano, recuperando la formación inicial de ataque, sistematizando los movimientos de permuta a los jugadores. Como podemos ver en la figura del jugador #10 regresa a la posición del jugador #4 y viceversa; así mismo, el jugador número #8 regresa a la posición del número #5 manteniendo el orden inicial. Ejercicio B.- Se coloca al equipo en modo defensa en presión media, el jugador #9 realiza acoso al jugador rival, es decir, estará con él con o sin balón mientras dure la jugada, los demás jugadores delanteros y defensas realizarán una cobertura zonal; los jugadores del medio campo, realizarán una marcación personal. Se comienza la jugada desde el arquero del equipo rival y se simulará un ataque organizado.","reglas":"El entrenador decide en qué momento se realiza el repliegue; se debe realizar movimientos de ataque por todas las zonas posibles; se debe reconocer la cobertura de inicio sin balón; se puede colocar un equipo contrario para reconocer las permutas por el lado de defensa; se puede practicar acoso general o parcial aplicando en un partido condicionado; se pueden aplicar coberturas mixtas en jugadas de pelota parada como tiros de esquina y tiros libre o cobro de falta desde zonas cercanas al área.","observaciones":"","movimientosObservar":"Repliegue en velocidad; todos los jugadores debe realizar marcación detrás de los rivales para cuidar sus espaldas; cuidar los perfiles y orientación de avance y repliegue; los desplazamientos laterales y de espalda.","codigo":"PTÁC-30","id":"libro-30","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-30.jpg"},{"nombre":"Estaciones de paredes en progresión","categoria":"Táctico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"15 metros de inicio a fin","duracion":"18","objFisico":"Afinar la aplicación de ritmo y sincronización en jugadas de parejas. Desarrollar capacidad aeróbica extensiva.","objTecnico":"Optimizar la utilización de pases cortos y paredes para una progresión elaborada. Reforzar los fundamentos tácticos de paredes para avanzar líneas de cobertura del rival.","objTactico":"Reconocer, aprender, repasar y perfeccionar tácticas en paredes y progresión en jugadas. Aplicar las habilidades de pase a un contacto para realizar paredes en progresiones efectivas.","objPsicologico":"Explicar los resultados que se obtiene aplicando automotivación en situaciones reales. Subir niveles de emotividad al trabajar con el respaldo de un compañero en misma sintonía.","materiales":"balones, conos bajos o platos, conos, chalecos o petos, mini portería","descripcion":"Estaciones de Paredes en progresión.- Superar líneas adversarias con la posesión y control del balón utilizando paredes simples. Nivel 1.- Se colocan platos en formación de triángulo, el jugador con chaleco o peto comenzará el ejercicio desde una esquina, pasa el balón al jugador que se encuentra estático en el plato amarillo y se desplazará al otro plato para recibir el balón. El jugador estático deberá pasar el balón a un solo contacto, el jugador con peto realiza dos contactos (recepción y pase).\n\nNivel 2.- Los jugadores trabajarán en parejas, se pasarán el balón de un lado para el otro en un sólo contacto por el medio de los obstáculos.\n\nNivel 3.- Se realiza en tres pasos: El jugador desde el punto \"1\" pasa el balón al jugador del punto \"2\" (ya sea el de la izquierda o derecha) realizando una pared a un contacto con relación al cono que simula un jugador rival, en el punto \"3\" el jugador realiza una definición a mini portería.","reglas":"Identificar parejas de jugadores afines y cerca a la posición de juego; se puede colocar un defensa con marcación en sombra; se puede colocar un portero en una portería para el momento de la definición; se pueden hacer dos paredes, es decir colocar una estación adicional de obstáculo antes de la definición; se puede armar la estación del nivel 3 en sectores laterales; se puede hacer un partido condicionado, el avance o el gol es válido únicamente si existe una pared anterior al sector deseado.","observaciones":"","movimientosObservar":"Pases con borde interno a ras de piso; recepción o control con borde interno; los tiempos de desplazamiento y pase; la fuerza de golpe del balón; la comunicación verbal y corporal; los perfiles para realizar las tareas con las dos piernas.","codigo":"PTÁC-31","id":"libro-31","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-31.jpg"},{"nombre":"Circuito de desdoble","categoria":"Táctico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"20 metros de inicio a fin","duracion":"18","objFisico":"Afinar la aplicación de espacio y coordinación en jugadas de parejas. Desarrollar capacidad aeróbica extensiva.","objTecnico":"Adaptar desplazamientos de desdobles para generar salidas por los extremos al recuperar el balón. Reforzar los fundamentos tácticos de desdobles para avanzar líneas de marcación del rival.","objTactico":"Reconocer, aprender, repasar y perfeccionar tácticas en desdobles para generar profundidad. Aplicar las habilidades de desplazamiento y recepción para realizar desdobles externos e internos.","objPsicologico":"Analizar los escenarios futuros aplicando autoconducta. Potenciar ese sentido agresividad para llegar con creatividad al área del rival.","materiales":"balones, conos bajos o platos, chalecos o petos, portería o mini portería","descripcion":"Circuito de desdoble.- Superar líneas defensivas en proyección y profundidad a espaldas de los jugadores rivales.\n\nNivel 1.- Se comenzará con el jugador que tiene el chaleco o peto, pasará el balón al jugador estático y hará un desplazamiento por su espalda hasta llegar al siguiente plato, el jugador realizará dos contactos (recepción y pase) cuando su compañero esté pasando por su espalda proyectará el pase correcto para que llegue con pelota dominada hacia el otro plato.\n\nNivel 2.- Similar a nivel uno, con desplazamiento frontal y continua hasta terminar los platos.\n\nNivel 3.- Se realiza en tres pasos: El jugador desde el punto \"1\" pasa el balón al jugador del punto \"2\" (ya sea el de la izquierda o derecha) pasa por la espalda y espera el pase, en el punto \"3\" el jugador termina con una definición a mini portería.","reglas":"Identificar parejas de jugadores afines y cerca a la posición de juego; se puede colocar un defensa con marcación en sombra; se puede colocar un portero en el arco para el momento de la definición; se pueden hacer dos desdobles, es decir colocar dos estaciones de obstáculo antes de la definición; se puede armar la estación del nivel 3 en sectores laterales; se puede hacer un partido condicionado, el avance o el gol es válido únicamente si existe desdoblamiento; se puede realizar pases a profundidad con el jugador desdoblado y terminar en centro.","observaciones":"","movimientosObservar":"Pases con borde interno a ras de piso; recepción o control con borde interno; los tiempos de desplazamiento y pase; la fuerza de golpe del balón; la comunicación verbal y corporal; los perfiles para realizar las tareas con las dos piernas.","codigo":"PTÁC-32","id":"libro-32","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-32.jpg"},{"nombre":"Presión en ocasiones de juego","categoria":"Psicológico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Anaeróbica","faseJuego":"Creación ofensiva","momentoJuego":"Ataque","tipoTarea":"","edad":"Todas las categorías","minJugadores":"","maxJugadores":"","espacio":"15 x 20 metros","duracion":"11","objFisico":"Potenciar adaptación y reacción de situaciones de alta intensidad. Aumento de resistencia anaeróbica y velocidad.","objTecnico":"Mejorar los pases y asegurar la salida de juego. Incrementar la velocidad, precisión y efectividad de pases y desplazamientos en el ataque.","objTactico":"Reconocer, aprender, repasar y perfeccionar los ritmos y los tiempos del partido. Desarrollar y progresar el fundamento táctico para manejar los ritmos y los tiempos del partido.","objPsicologico":"Intensificar y dominar el autocontrol enfocado en emociones. Regular la frecuencia de emotividad con el equipo.","materiales":"balones, chalecos o petos, cinta elástica (5 m), porterías","descripcion":"Ejercicio A.- Se arma un rectángulo con cintas elásticas o conos bajos para realizar un rondo con apoyos. Se conforman equipos de cuatro personas, se colocan dos jugadores laterales que serán comodines y jugarán con el equipo que tiene el balón; los porteros se colocarán en los otros extremos y apoyarán a un solo equipo. Los equipos de adentro realizarán la mayor cantidad de pases apoyándose con los comodines y portero. Se realizan varias simulaciones o casos en los cuales varía el tiempo restante del partido y marcador adverso o a favor.\n\nEjercicio B.- Se conforman dos equipos en igualdad numérica y realizamos un partido condicionado en espacio reducido o doble área. El objetivo del ejercicio es provocar a los jugadores todos los pasajes de un partido. Las instrucciones se cambiarán constantemente para el equipo azul, simulando tener marcadores adversos por uno o más goles de tal manera se varían las intensidades en las jugadas. El equipo también debe manejar adecuadamente los ritmos con resultado a favor. Las variables de resultado y tiempo las realiza el entrenador para generar el mayor estrés y confianza en los jugadores.","reglas":"Generar la mayor cantidad de estrés en los jugadores; se pueden hacer partidos condicionados con todos los jugadores disponibles; se puede hacer jugadas de balón parado con condiciones de \"última jugada\"; se pueden hacer simulaciones de penales; se puede utilizar ciertos fallos a favor o en contra para generar tensión en los tiempos del partido; se puede simular expulsiones para condicionar situaciones de crisis.","observaciones":"","movimientosObservar":"La intensidad en los tiempos de reacción; identificar a jugadores que responden bien ante condiciones de presión; identificar y alentar y a los jugadores que actúan inadecuadamente bajo presión; calma y paciencia en las jugadas; confianza y estabilidad en resultado a favor.","codigo":"PTÁC-33","id":"libro-33","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-33.jpg"},{"nombre":"Orientación defensiva con portero","categoria":"Físico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Iniciación","momentoJuego":"Defensa","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"16","espacio":"10 metros de inicio a fin","duracion":"8","objFisico":"Reconocer, aprender, repasar y perfeccionar la orientación dentro del campo y adaptación al entorno. Aumento de resistencia aeróbica extensiva.","objTecnico":"Potenciar la entrada, anticipación e interceptación utilizando una correcta orientación defensiva. Desarrollar capacidades coordinativas en conducción hacia el arco.","objTactico":"Utilizar la correcta orientación corporal y de espacio para defender. Incrementar la visión de ataque con una adecuada orientación y perfil.","objPsicologico":"Ampliar la utilización de autoconfianza en sus movimientos y jugadas. Extender el sentido de persistencia en jugadas y repeticiones.","materiales":"balones, chalecos o petos","descripcion":"Se coloca un atacante, un defensa y un portero, los tres con colores distintos. El delantero realiza un desplazamiento sin balón hacia los balones que se encuentran distribuidos en la mitad del campo, al hacer contacto con cualquier balón realizará una conducción en forma directa hacia la portería, el defensa interactúa y se desplaza de izquierda a derecha de acuerdo a la dirección que el atacante cerrando el paso del avance con la portería en sus espaldas.\n\nEl portero también deberá moverse dentro del área marcada con relación a la línea de avance cuidando siempre el primer parante y listo por si el atacante supera al defensa y salir para achicar el tiro, reduciendo espacios a portería.","reglas":"El atacante puede realizar conducción rápida y regresa al inicio cuando su camino sea interceptado; el defensa puede actuar en marcación sombra o real para detener el balón; el atacante puede realizar un dribling o finta al defensa y posteriormente una definición. Nunca detenerse; el defensa podrá marca únicamente afuera del área de meta; el portero podrá salir a interceptar o bloquear el balón únicamente cuando el delantero se encuentre dentro del área; se pueden asignar puntos a los tres jugadores de acuerdo a su desempeño en la jugada.","observaciones":"","movimientosObservar":"Conducción con borde externo; velocidad de conducción y tiempos de acercamiento al arco; perfil y orientación del defensa; el portero debe tener comunicación constante con el defensa; cabeza levantada de los 3 jugadores.","codigo":"PFísCo-34","id":"libro-34","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-34.jpg"},{"nombre":"Estaciones de equilibrio y postura","categoria":"Físico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"20","espacio":"8 metros de inicio a fin","duracion":"18","objFisico":"Reconocer, aprender, repasar y perfeccionar la postura para mejorar el equilibrio y respuesta de reacción. Aumento de fuerza y postura.","objTecnico":"Mejorar desplazamientos, saltos y cargas con equilibrio.","objTactico":"Potenciar el apoyo y la reacción en jugadas cortas.","objPsicologico":"Agudizar el valor del autoentrenamiento dentro de cancha. Renovar estados de motivación al mejorar sus movimientos.","materiales":"balones, conos bajos o platos, vallas, banca, cinta elástica (5 m), escaleras de coordinación, aros o anillos, bosu","descripcion":"Estación \"A\".- Pisando siempre en la parte central de las escaleras y aros el jugador pasará con un solo pie (izquierdo o derecho) el trayecto en su totalidad o parcial.\n\nEstación \"B\".- El jugador deberá pisar una línea delgada colocando un pie adelante del otro con pasos cortos avanzando de una forma segura, saltará al banco o superficie un poco alta y lo realizará de misma manera.\n\nEstación \"C\".- El jugador con un solo pie saltará las vallas de forma lateral equilibrándose y haciendo contrapeso con el brazo contrario a la pierna que salta.\n\nEstación \"D\".- El jugador se colocará con un solo pie sobre el bosu, alternado con otro pie después de haber logrado un adecuado equilibrio.\n\nEstación \"E\".- El jugador se colocará con los dos pies sobre el bosu y orbitará un balón generando movimiento a todas las direcciones.","reglas":"Estación \"A\" se puede jugar con reglas de la rayuela; estación \"B\" se puede hacer impactos leves con balones o pelotas para generar distracción; estación \"C\" se puede recoger objetos del suelo antes de hacer el salto; se puede subir al Bosu con salto en dos piernas o una sola; al bosu se puede aumentar o disminuir la presión interna para dificultar o facilitar el ejercicio; dependiendo de la edad se puede utilizar una pelota medicinal en la estación \"E\".","observaciones":"","movimientosObservar":"Postura firme y erguida en todos las estaciones; en cada salto debe asentar totalmente la planta del pie para realizar el siguiente salto; los brazos abiertos para realizar contrapeso; en el bosu puede bajar un poco el centro de gravedad; repetir estaciones que no ha dominado.","codigo":"PFísCo-35","id":"libro-35","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-35.jpg"},{"nombre":"Estaciones de sincronización","categoria":"Físico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica intensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"20","espacio":"10 metros de inicio a fin","duracion":"21","objFisico":"Reconocer, aprender, repasar y perfeccionar la sincronización de ojo - balón - contacto del cuerpo. Aumento de velocidad y capacidad aeróbica con ritmo.","objTecnico":"Mejorar desplazamientos, conducción, dribling, anticipaciones y definiciones sincronizando movimientos en jugadas.","objTactico":"Afinar ritmos para mejorar paredes, desdobles, repliegues y proyecciones.","objPsicologico":"Reforzar la herramienta de autocorrección en movimientos y jugadas. Elevar los niveles de concentración en movimientos y jugadas.","materiales":"balones, escaleras de coordinación, conos, estacas o picas, cinta elástica (5 m), conos bajos o platos","descripcion":"Estación \"A\".- Se colocan las escaleras en paralelo para poder realizar ejercicio de ida y regreso. Colocamos un jugador atrás de otro que pasarán las escaleras pisando en la parte central y con una diferencia de cuatro escalones. Las diferentes formas de pasar las escaleras son: Una, dos y tres pisadas en cada espacio; un pie adentro otro afuera, entrada y salida con un pie y dos pies, paso lateral izquierda y derecha, zigzag en aumento, abriendo y cerrando las piernas, carrusel, cruce de piernas en pisada, etc.\n\nEstación \"B\".- Los jugadores deberán desplazarse lateralmente en zigzag o eslalon por afuera de la estaca en dos, tres o cuatro pasos. Estación \"C\".- Los jugadores se desplazan siempre de frente con rodillas alzadas haciendo eje en cada cono.\n\nEjercicio \"D\".- Los jugadores se encuentran cada uno con un balón en una zona marcada de la cancha. Los jugadores lanzan el balón con la mano lo más alto posible y el entrenador indica con que parte del cuerpo receptan el balón. Las superficies a contactar son: mano, punta de pie, empeine, borde interno, borde externo, muslo, pecho, hombro, cabeza con salto y sin salto.","reglas":"El paso de las escaleras deben ir desde el movimiento más fácil hasta el más complejo; si un a un jugador se le complica un ritmo o sincronización debe repetirlo; el jugador de atrás debe igualar el ritmo del jugador que va adelante; en el ejercicio \"D\", se puede golpear el balón con empeine hacia arriba; en el ejercicio \"D\", se pueden hacer parejas con un balón. El jugador lanza en pase alto y media altura para sincronizar la recepción o amortiguamiento con borde interno, borde externo, taco, planta, etc; el entrenador también puede asistir con balones altos y fuertes desde afuera de la zona.","observaciones":"","movimientosObservar":"Primero debe demostrar el entrenador especialmente la primera repetición; la postura debe ser erguida; brazos en movimiento y en ritmo al paso; en movimiento de espaldas el jugador debe regresar a ver rápidamente para que su visión predomine hacia adelante.","codigo":"PFísCo-36","id":"libro-36","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-36.jpg"},{"nombre":"Estaciones de velocidad","categoria":"Físico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Velocidad máxima","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"4","maxJugadores":"20","espacio":"4 metros de inicio a fin","duracion":"14","objFisico":"Aumentar velocidad de reacción, desplazamiento, competitiva y aceleración. Estimular y activar fibras blancas musculares.","objTecnico":"Potenciar velocidad en desplazamientos para llegar primero al balón en defensa. Incrementar velocidad en desplazamientos y conducción para ser eficientes en el ataque.","objTactico":"Aplicar velocidad en las jugadas como desdobles, repliegues, pases a profundidad, definiciones, fintas, etc.","objPsicologico":"Reforzar la herramienta de auto entrenamiento dentro del campo. Transmitir confianza y motivación a los compañeros en trabajo de equipo.","materiales":"balones, escaleras de coordinación, vallas, estacas o picas, varas, conos bajos o platos, chalecos o petos, aros o anillos","descripcion":"Estación \"A\". - Saltar la vallas en uno o dos pisadas en el menor tiempo posible.\n\nEstación \"B\".- Pasar la escalera de frente en dos o tres pisadas lo más sincronizado y rápido posible.\n\nEstación \"C\".- Pasar los aros o ulas abriendo ligeramente las piernas lo más pronto posible.\n\nEstación \"D\".- Pasar por entre las estacas en forma de eslalon con los pasos más corto posible equilibrándose con los brazos en el menor tiempo. Estación \"E\".- Pasar la escalera de forma lateral, entrando y saliendo en cada uno de los espacios lo más rápido posible.\n\nEstación \"F\".- Saltar las varas de un lado al otro con movimientos rápidos.\n\nEstación \"G\".- Desplazamiento frontal y recto, explosivos al inicio y con freno muy extenso.\n\nEjercicio \"H\".- Se colocan dos juegos de estacas de colores simétricas en un espacio de la cancha. Se dividen a los jugadores en dos equipos, similares en velocidad. Antes de la señal de partida el entrenador indica por cual estaca deberán recorrer antes de llegar a la meta.","reglas":"Estación \"A\" pueden pasarlo lateralmente o con tranco largo; estación \"C\" pueden pisar entre los espacios vacíos de los aros para hacer pasos más pequeños; estación \"D\" pueden pasarlo de espaldas; estación \"F\" en cada vara pueden hacer tres o cuatro saltos dependiendo de la edad; ejercicio \"H\" se pueden formar parejas de una similar velocidad para generar competencia; se pueden hacer competencias con todo el equipo, el jugador podrá salir después que su compañero haya pasado la meta. Se puede hacer con conducción de balón.","observaciones":"","movimientosObservar":"Movimiento de brazos rápidos en sincronización con las piernas; bajar el centro de gravedad para el control del ejercicio y cambio de sentido; utilizar punta de pie en las pisadas; extender toda la pierna y la punta del pie en trayectos largos.","codigo":"PFísCn-37","id":"libro-37","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-37.jpg"},{"nombre":"Estaciones de salto y fuerza","categoria":"Físico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Umbral o zona mixta","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"Circuito","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"26","espacio":"5 metros de inicio a fin","duracion":"8","objFisico":"Desarrollar, aumentar y potenciar fuerza en tren inferior y abdominal. Estimular y activar fibras rojas musculares.","objTecnico":"Ampliar el rango de salto, despeje y pase largo; mejorar apoyo en carga, entrada y anticipación. Incrementar fuerza en salto, pase largo y remate; soportar de mejor manera carga y anticipación.","objTactico":"Mejorar el salto en jugadas de balón parado aéreo.","objPsicologico":"Convencer que la herramienta de autoconfianza es fundamental para fortalecer cuerpo y mente. Fomentar confianza y responsabilidad para proteger a los compañeros.","materiales":"balones, escaleras de coordinación, vallas, valla alta, pesas, conos bajos o platos, bosu, aros o anillos","descripcion":"Estación \"A\".- Saltar la vallas con dos piernas flexionadas desde el impulso hasta el apoyo final.\n\nEstación \"B\".- Saltar cada uno de los espacios de las escaleras con un solo pie.\n\nEstación \"C\".- Saltar los aros lateralmente, impulsándose con una pierna y aterrizando con la otra, aplicando equilibrio en todo momento. Estación \"D\".- Equilibrar encima del bosu con dos o una sola pierna.\n\nEstación \"E\".- Fuerza estática, sostener peso, levantar mancuernas. Recomendable para mayores de 14 años.\n\nEstación \"F\".- Saltar la cuerda con coordinación lo más rápido posible.\n\nEstación \"G\".- Utilizar mancuernas o barra con pesas flexionando brazos, piernas y abdominales (mayores de 16 años).\n\nEjercicio \"H\".- Se colocan varios balones al frente de la portería para rematar con fuerza y precisión para hacer la mayor cantidad de goles.","reglas":"Variantes: manejar las alturas de las vallas de acuerdo a la edad o de la capacidad del jugador; el salto equilibrado y siempre controlado; el ejercicio en estática puede ser el mismo o cambiar en cada repetición; en los ejercicios de estática siempre colocar estómago fuerte y se los puede hacer en conjunto con todos los jugadores al finalizar el entrenamiento o las estaciones; en el ejercicio \"H\" se puede cambiar rematar de frente o de los costados, en la portería se coloca un portero; realizar el remate con empeine e impactar en todo el centro del balón.","observaciones":"","movimientosObservar":"El impulso de salto debe ser bajando el centro de gravedad; siempre levantarse lo más alto del suelo; las rodillas en el salto hacia el frente; piernas juntas todo el tiempo; los ejercicios estáticos en posición recta; p- Motivación constante ante el esfuerzo.","codigo":"PFísCn-38","id":"libro-38","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-38.jpg"},{"nombre":"Circuito de resistencia","categoria":"Físico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Anaeróbica","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"Circuito","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"22","espacio":"40 metros de inicio a fin","duracion":"24","objFisico":"Desarrollar, aumentar y potenciar resistencia para acortar el tiempo de recuperación entre esfuerzos. Estimular y fortalecer fisiología cardíaca.","objTecnico":"Incrementar resistencia para apoyar constantemente en todos los gestos técnicos que requieren un partido, especialmente desplazamientos, conducciones y definiciones.","objTactico":"Elevar la capacidad de resistencia aeróbica, mixta y anaeróbica para mantener ritmos e intensidades durante los partidos.","objPsicologico":"Prosperar la automotivación para alcanzar metas específicas. Fomentar el sentido de sacrificio y creatividad para objetivos.","materiales":"balones, conos bajos o platos, vallas, estacas o picas, conos, cinta elástica (5 m)","descripcion":"Circuito de resistencia.- Está diseñado para realizarlo en parejas, para desviar la atención del jugador se lo realiza con balón de tal manera que se pueden alcanzar distancias largas.\n\nTrayecto \"A'\".- Se realizan paredes que aumentan paulatinamente la distancia ampliando el rango de zancada.\n\nTrayecto \"B\".- Uno de los jugadores se desplaza de frente y el otro de espaldas, se realizan pases mientras superan los platos como referencia. Trayecto \"C\".- Desplazamientos con desdobles a la espalda del compañero.\n\nTrayecto \"D\" - Avances frontales tipo paredes. Se coloca una cinta elástica a un altura de 40 centímetros amarrados entre las estacas para que el balón pueda pasar por encima de la cinta.\n\nTrayecto \"E\".- El balón pasa por debajo de las vallas y los jugadores se desplazan alternando el lado izquierdo y derecho con el balón.","reglas":"Variantes: se puede hacer un par de vueltas sin balón para elevar la carga deseada; se puede realizar primero con mano para después realizarlo con pie; se puede cambiar la velocidad de los desplazamientos, siempre y cuando sean constantes; se puede agregar otro trayecto sin obstáculos para desplazamiento lineal; cronometrar la vuelta del circuito para controlar de mejor forma las resistencias de las parejas; se deben tener balones al principio y al final de los trayectos por si se desvía a otro lugar.","observaciones":"","movimientosObservar":"Constante motivación durante el trabajo; alentar a los que realizan correctamente la tarea; identificar los jugadores que poseen poca resistencia para alargar futuros entrenamientos; la respiración del descanso debe ser profunda; hidratar brevemente cada 3 o 4 vueltas; realizar la sumatoria del recorrido.","codigo":"PFísCn-39","id":"libro-39","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-39.jpg"},{"nombre":"Momento de elongación o estiramiento","categoria":"Físico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Calentamiento o regenerativo","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"","maxJugadores":"","espacio":"","duracion":"5","objFisico":"Desarrollar, aumentar y potenciar flexibilidad para movimientos veloces. Estimular y mejorar elasticidad en músculos y ligamentos para evitar lesiones.","objTecnico":"Incrementar flexibilidad para mejorar anticipaciones, interceptaciones, entradas, dribling y conducción.","objTactico":"Elevar la capacidad de zancada y velocidad en repliegues y transiciones.","objPsicologico":"Acostumbrar al jugador a auto entrenarse en todo lugar. Ampliar la responsabilidad de mejorar todos los días.","materiales":"","descripcion":"Momento de elongación o estiramiento.- Permite a los jugadores regresar a la calma y complementar el ejercicio de todo el entrenamiento, Cada una de las gráficas muestra el tipo de estiramiento que pueden realizar los jugadores y los músculos que trabajan en cada uno. Pueden hacerlo de forma parada aunque después del entrenamiento se recomienda hacerlo en el suelo.\n\nEn el estiramiento asistido pueden hacerlo entre parejas, aunque para evitar sobre esfuerzos es mejor que lo realice el entrenador.","reglas":"Cada jugador debe tener en cuenta la importancia del estiramiento adecuado; el jugador debe caminar con sus dedos para alcanzar un mejor estiramiento; el estiramiento también se puede hacer con balón; explicar qué músculo o nombre tiene cada estiramiento para que el alumno comprenda e identifique el ejercicio que está haciendo para sesiones posteriores; se puede delegar a un jugador rotativo para que comande o lidere los estiramientos; se puede utilizar el espacio para charlas informativas y feedback del entrenamiento.","observaciones":"","movimientosObservar":"Las piernas deben estar bien estiradas y rectas; mantener posición estática durante el ejercicio; motivar al jugador que vaya siempre a otro nivel; concentración y silencio de los jugadores; elegir al mejor o mejores jugadores del entrenamiento para ser reconocido con un aplauso o como en entrenador decida.","codigo":"PFísCn-40","id":"libro-40","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-40.jpg"},{"nombre":"Todos o nadie","categoria":"Psicológico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"20","espacio":"9 metros de inicio a fin","duracion":"15","objFisico":"Afinar sincronización y equilibrio en salto con uno o dos pies. Aumentar fuerza de piernas en zona aeróbica.","objTecnico":"Mejorar desplazamiento frontal en salto y la elevación de salto para cabecear.","objTactico":"Enriquecer la comunicación del equipo para jugadas de pelota parada.","objPsicologico":"Fortalecer las herramientas de autoconducta, autocontrol, autorregulación y autoconfianza para actividades de equipo. Engrandecer y fomentar trabajo en equipo, liderazgo, responsabilidad, concentración, solidaridad y emotividad.","materiales":"escaleras de coordinación, valla alta, conos bajos o platos, cinta elástica (5 m)","descripcion":"El trayecto todos o nadie.- Diferencia en trabajo grupal versus el trabajo de equipo.\n\nSe arma con los implementos de acuerdo a la figura. Todos los jugadores deben estar en un lado del ejercicio y el objetivo es que pasen sin excepción de uno en uno al otro lado donde se encuentra la zona final. Las reglas de pasar el trayecto son las siguientes: Saltar el primer obstáculo con dos pies juntos; al pasar la zona de las líneas deberá colocar los dos pies cuando el color es amarillo, pie izquierdo color verde, pie derecho en color rojo, los dos pies afuera de la escalera en el color azul, en el color blanco no se pisa y por último salto con dos pies por encima de la valla alta. Si logra pasar correctamente, el jugador se quedará en ese lugar. Si en algún momento un jugador comete un error, todos regresarán al principio y se reinicia el ejercicio.","reglas":"Variantes: se puede colocar una sola escalera con niños de 8 a 10 años; si un segundo jugador ingresa al área de escaleras todos regresan al inicio; si un jugador toca cualquier parte de la escalera, regresan todos; si el jugador toca con cualquier parte del cuerpo la valla alta se considerará como falla; los jugadores que han pasado al otro lado pueden dirigir e instruir a los que se encuentran pasando; se puede hacer el trayecto de ida y reversa cambiando las reglas de los colores; se otorgan como premio omisiones de fallas cuando haya pasado el 80% o 90% del equipo.","observaciones":"Recomendado en pretemporada o cuando hay etapas de bajos resultados.","movimientosObservar":"El entrenador debe actuar como veedor y juez, siendo estricto, transparente y honesto; concientizar cada 15 minutos el resultado que van obteniendo como equipo; identificar a los líderes, participantes y veedores; identificar las emociones de los jugadores; anotar todo para la charla y feedback.","codigo":"PPsico-41","id":"libro-41","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-41.jpg"},{"nombre":"Tu idea siempre vale","categoria":"Psicológico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Calentamiento o regenerativo","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"14","maxJugadores":"26","espacio":"10 m²","duracion":"20","objFisico":"Fomentar sincronización y ritmo de movimientos. Aumentar velocidad de reacción en movimientos en zona aeróbica.","objTecnico":"Mejorar pases con la mano y con el pie.","objTactico":"Sumar apoyo y creatividad en las jugadas.","objPsicologico":"Fortalecer las herramientas de autocorrección, autorregulación y automotivación para actividades de equipo. Potenciar liderazgo, creatividad y confianza en trabajo de equipo.","materiales":"balones, chalecos o petos","descripcion":"Ejercicio: tu idea siempre vale.- La sumatoria de ideas y opiniones hacen que funcionen las cosas.\n\nSe divide a todos los integrantes en dos equipos cada uno con un balón y con diferentes espacios. El objetivo del juego es que todos los integrantes del equipo toquen el balón en el menor tiempo posible. Las reglas dentro del tiempo son las siguientes: el primer jugador que tiene el balón deberá también finalizar con el balón; no se puede pasar el balón ni a la izquierda ni a la derecha; si el balón cae al suelo se anula el conteo del tiempo; y, se realiza el conteo del tiempo siempre y cuando hayan repasado varias veces su jugada.\n\nSe alterna la toma de tiempo de un equipo al otro.","reglas":"Variantes: se puede dividir a todos los jugadores en tres equipos para generar mayor competencia; cada vez que el equipo obtenga un tiempo se le reta para que puedan mejorarlo; incentivar la creatividad y la forma de resolver el ejercicio; el toque puede ser con cualquier parte del cuerpo o con pie únicamente; como dato confidencial a los jugadores este ejercicio se lo puede resolver en menos de un segundo; si es permitido copiar los movimientos o tácticas de los otros equipos si el objetivo es mejorarlo; se pueden por último unir los tres equipos para demostrar el resultado final.","observaciones":"","movimientosObservar":"El entrenador debe actuar como veedor y juez, siendo estricto, transparente y honesto; para resultados diferentes deben aplicarse tácticas y estrategias diferentes; identificar a los líderes, participantes y veedores; identificar las emociones de los jugadores; anotar todo para la charla y feedback.","codigo":"PPsico-42","id":"libro-42","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-42.jpg"},{"nombre":"Adelante y en equipo","categoria":"Psicológico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Aeróbica extensiva","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"8","maxJugadores":"22","espacio":"15 metros de inicio a fin","duracion":"5","objFisico":"Desarrollar sincronización con cualquier parte del cuerpo. Ganar velocidad competitiva en zona aeróbica.","objTecnico":"Mejorar el control y pases de balones a media altura y aéreos.","objTactico":"Intensificar el apoyo entre jugadores con control continuo del balón aplicando ritmos y tiempos.","objPsicologico":"Fortalecer las herramientas de autoentrenamiento y autoconducta en tareas de equipo. Progresar la motivación en trabajo en equipo.","materiales":"balones, chalecos o petos, cinta elástica (5 m)","descripcion":"Adelante y en equipo.- El apoyo de cada unos de los jugadores logra el objetivo.\n\nSe colocan dos cintas a lo largo del campo señalando en principio y el final. Se divide a todos los integrantes del equipo en 3 o 4 equipos diferentes e identificados con colores. El objetivo del juego es que llevar el balón hasta la línea contraria en equipo. Las reglas dentro del trayecto son las siguientes: todos los equipos salen al mismo tiempo; el balón debe pasar entre todos los jugadores mientras avanzan conjuntamente a la meta; el balón debe mantenerse siempre en el aire; se puede tocar con cualquier parte del cuerpo excepto la mano; cada jugador debe impactar el balón una sola vez; si el balón cae regresarán a la línea de inicio; y, el equipo que llegue debe pasar cada uno de sus integrantes la línea para obtener la victoria.","reglas":"Variantes: con niños de 8 a 10 años se puede impactar con mano, El trayecto puede ser de ida y vuelta; limitar los impactos con un solo contacto del cuerpo, solo cabeza, solo pie, etc; la meta final puede ser un tacho o contenedor grande para insertar el balón; los equipos pueden partir desde las esquinas del espacio o la cancha en dirección al centro donde se encuentra el tacho o bote, quien inserte primero el balón ganará los puntos; el ejercicio se puede hacer a contratiempo para generar presión; se juntan a todos equipos para hacer el mismo ejercicio.","observaciones":"","movimientosObservar":"El entrenador debe actuar como veedor y juez, siendo estricto, transparente y honesto; el golpe del balón siempre para arriba; la forma circular de avanzada; identificar las emociones de los jugadores; identificar el liderazgo de los equipos; p- Anotar todo para la charla y feedback.","codigo":"PPsico-43","id":"libro-43","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-43.jpg"},{"nombre":"Todos en uno","categoria":"Psicológico","tipoEjercicio":"Ejercicio analítico","zonaTrabajo":"Calentamiento o regenerativo","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"10","maxJugadores":"20","espacio":"1,3 m²","duracion":"10","objFisico":"Aumentar equilibrio con contactos. Ganar fuerza máxima y estática.","objTecnico":"Tolerar contactos y pesos en la carga.","objTactico":"Prosperar el trabajo de cobertura y acoso.","objPsicologico":"Elevar sentidos de autoconfianza y autoconducta. Progresar la solidaridad de equipo y liderazgo positivo.","materiales":"cinta elástica (5 m)","descripcion":"Todos en uno.- La fuerza y la solidaridad de todos en conjunto crean increíbles resultados.\n\nSe arma con la cinta un cuadrado con las dimensiones recomendadas por edades. Actúan todos los integrantes del equipo, los cuales deben encontrarse con pantalón de calentador o chándal y camiseta o ropa cómoda. El objetivo del juego es que todos deben mantenerse dentro del perímetro durante un tiempo determinado, el tiempo recomendado es de 30 segundos. Las reglas del ejercicio son las siguientes: pisar dentro de la línea marcada y todos deben tocar el suelo con cualquier superficie del cuerpo.","reglas":"Variantes: se aumentan los jugadores de uno en uno o en parejas, diferenciando el espacio que se reduce; si se consigue el objetivo en corto tiempo se reduce el espacio del cuadrado; se puede cambiar la forma de la figura como triángulo, estrella o irregular; se puede realizar encima de una base fuerte cuadrangular de una altura de 15 centímetros; el cuerpo técnico también puede participar en el ejercicio; el entrenador o Director Técnico también puede ingresar al último del ejercicio.","observaciones":"Muy recomendable utilizar en pretemporada o en periodos de bajos resultados.","movimientosObservar":"El entrenador debe actuar como veedor y juez, siendo estricto, transparente y honesto; el golpe del balón siempre para arriba; la forma circular de avanzada; identificar las emociones de los jugadores; identificar el liderazgo de los equipos; anotar todo para la charla y feedback.","codigo":"PPsico-44","id":"libro-44","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-44.jpg"},{"nombre":"Tres en raya","categoria":"Psicológico","tipoEjercicio":"Ejercicio integral","zonaTrabajo":"Velocidad máxima","faseJuego":"Vacío","momentoJuego":"Vacío","tipoTarea":"","edad":"Todas las categorías","minJugadores":"6","maxJugadores":"14","espacio":"12 metros de inicio a fin","duracion":"6","objFisico":"Afinar capacidades de adaptación, sincronización y ritmo. Intensificar velocidad de reacción y competitiva.","objTecnico":"Aumentar velocidad en desplazamientos frontales.","objTactico":"Progresar las condiciones de apoyo y control de tiempos del partido.","objPsicologico":"Incrementar sentidos de autorregulación y automotivación. Agudizar concentración y atención en jugadas.","materiales":"chalecos o petos, conos bajos o platos, red de suelo","descripcion":"Tres en raya.- La decisión de mi compañero me ayuda a obtener resultados.\n\nSe coloca la red de suelo de 9 espacios 3x3, o a su vez lo podemos formar con cintas elásticas. Se forman equipo de hasta 5 integrantes y se los identifica con algún color. El objetivo del juego es ganar el clásico juego de tres en raya, formando tres colores seguidos dentro de la red en dirección horizontal, vertical o diagonal. Las reglas del ejercicio son las siguientes: El primero, segundo y tercer integrante deberán tener un plato del mismo color en sus manos; a la señal el primer jugador saldrá a toda velocidad para colocar en un espacio vacío de la red y regresar caminando al inicio; los siguientes jugadores saldrán en el momento que el plato se encuentre colocado dentro de la red; el cuarto y el quinto jugador, en su turno, podrán mover los platos de adentro y se repetirá hasta que alguno de los 2 equipos logre tres en raya.","reglas":"Variantes: el desplazamiento puede ser en zigzag u ondulatorio colocando conos como obstáculos; al inicio de la partida se puede colocar una escalera para sincronizar en dos pisadas; antes del desplazamiento los jugadores pueden estar arrodillados, sentados, acostados; en el trayecto se puede conducir con balón; se pueden colocar entre dos o tres vallas al inicio vallas para que puedan saltar; se pueden otorgar puntos extras cuando se forme el tres en raya diagonal, etc.","observaciones":"","movimientosObservar":"El entrenador debe actuar como veedor y juez, siendo estricto, transparente y honesto; braceo durante el desplazamiento; identificar las emociones de los jugadores; identificar el liderazgo de los equipos; anotar todo para la charla y feedback.","codigo":"PPsico-45","id":"libro-45","origenCatalogo":"2026-11b","origenLibro":true,"imagen":"/images/tareas-libro/tarea-45.jpg"}];
